-- Loot Guide texts in Russian (ruRU).
-- Source language: US English (the keys). Written by the EldoUI authors, game
-- terms as the ruRU client uses them. Keep every %s, %d and |c...|r code.
-- Built with the key list of tools/locale/lootguide-template.lua; a missing key
-- shows the English text. Loads only on a ruRU client.
local _, E = ...
if GetLocale() ~= "ruRU" then return end
