	["5 players"] = "5 игроков",
	["<1m"] = "<1 мин.",
	["[bis | char | stop]  the Loot Guide simulator: open its window, or start or stop a run"] = "[bis | char | stop]  симулятор Loot Guide: открыть его окно или начать либо остановить прогон",
	["[data | reset | <text>]  open or close the Loot Guide (also /lg)"] = "[data | reset | <текст>]  открыть или закрыть Loot Guide (также /lg)",
	["[name | probe | check]  the Loot Guide on the Attunements tab; probe and check are for testers"] = "[name | probe | check]  Loot Guide на вкладке «Допуски»; probe и check нужны тестерам",
	["[on | off | toggle | <section>]  My Adventure: switch it, open its settings, or open a section"] = "[on | off | toggle | <раздел>]  Мои приключения: включить или выключить, открыть настройки или раздел",
	["[on | off | toggle | data | reset | <text>]  the Loot Guide: switch it, or same as /lg"] = "[on | off | toggle | data | reset | <текст>]  Loot Guide: включить или выключить, или то же, что /lg",
	["[section | data | check | report | export | import | text]  open or close My Adventure in the Journal window, on a section or searched; check the journal data after a patch; report new content; export your journal (markdown, html, text or code); import from Forever Journal or a code"] = "[section | data | check | report | export | import | text]  открыть или закрыть «Мои приключения» в окне дневника, на разделе или с поиском; проверить данные дневника после обновления; сообщить о новом контенте; экспортировать дневник (markdown, html, текст или код); импортировать из Forever Journal или кода",
	["[section | data | text]  open or close My Adventure in the Journal window, on a section or searched"] = "[section | data | text]  открыть или закрыть «Мои приключения» в окне дневника, на разделе или с поиском",
	["[text]  write a note in your journal here and now, or open the quick note card"] = "[текст]  написать заметку в дневник здесь и сейчас или открыть карточку быстрой заметки",
	["A button on keepsake and level moments. A click closes the card and takes a screenshot without it. Nothing is taken by itself."] = "Кнопка у памятных моментов и моментов уровня. Нажатие закрывает карточку и делает снимок экрана без нее. Само по себе ничего не снимается.",
	["A check is already running."] = "Проверка уже идет.",
	["A companion's recorded time is outside the supported range."] = "Записанное время спутника вне допустимого диапазона.",
	["a cooldown kept for hard fights"] = "восстановление, приберегаемое для трудных боев",
	["A corner of %s"] = "Уголок: %s",
	["A creature of this event."] = "Существо этого события.",
	["A creature or chest that drops the recipe."] = "Существо или сундук, с которого падает рецепт.",
	["A dungeon"] = "Подземелье",
	["a dungeon"] = "подземелье",
	["A first boss kill waits at the end of a dungeon. These fit your level:"] = "Первая победа над боссом ждет в конце подземелья. Эти подходят вашему уровню:",
	["A friend or group member..."] = "Друг или член группы...",
	["A Journal button on the minimap: left-click opens My Adventure, right-click writes a quick note, drag it to move it around the edge. The Minimap module's button bin gathers it."] = "Кнопка дневника у мини-карты: левый щелчок открывает «Мои приключения», правый пишет быструю заметку, перетащите ее, чтобы двигать по краю. Сборщик кнопок модуля «Мини-карта» забирает ее.",
	["A Journal button under EldoUI's in the Esc menu: click opens My Adventure, right-click writes a quick note."] = "Кнопка дневника под кнопкой EldoUI в меню Esc: щелчок открывает «Мои приключения», правый щелчок пишет быструю заметку.",
	["A journal kept since %s."] = "Дневник ведется с %s.",
	["A letter from the Scarshield Quartermaster in Blackrock Spire sends you to the orb behind General Drakkisath, which opens Blackwing Lair."] = "Письмо интенданта Изрубленного Щита в пике Черной горы отправляет вас к сфере за генералом Драккисатом, которая открывает Логово Крыла Тьмы.",
	["A line from your story under each chapter title and another after its moments, told in the tone you picked on the Story tab. Level view only."] = "Строка из вашей истории под каждым заголовком главы и еще одна после ее моментов, в тоне, выбранном на вкладке «История». Только в виде по уровням.",
	["A little high for you: a level %d quest."] = "Немного высоко для вас: задание %d-го уровня.",
	["A little high for you: it starts at level %d."] = "Немного высоко для вас: начинается с %d-го уровня.",
	["A little low for you: it is %d-%d."] = "Немного низко для вас: уровни %d-%d.",
	["A long break"] = "Долгий перерыв",
	["a long cooldown kept for hard fights"] = "долгое восстановление, приберегаемое для трудных боев",
	["A milestone to look forward to."] = "Веха, которую стоит ждать.",
	["A moment in your journal"] = "Момент в вашем дневнике",
	["A new goal"] = "Новая цель",
	["A note"] = "Заметка",
	["A note remembers where and when you wrote it, and it can remind you later."] = "Заметка помнит, где и когда вы ее написали, и может напомнить о себе позже.",
	["A note remembers where and when you wrote it. It can remind you later."] = "Заметка помнит, где и когда вы ее написали. Она может напомнить о себе позже.",
	["a one-minute bane; Bane of Agony is used"] = "проклятие на минуту; используется Проклятие агонии",
	["A one-time reminder moves to the archive once it has fired or you mark it done."] = "Разовое напоминание уходит в архив, когда сработает или когда вы отметите его выполненным.",
	["A page of My Adventure"] = "Страница «Моих приключений»",
	["A pin on the world map for each giver of the quests left in the zone the map shows. Hover it for the quests, click it for a waypoint. The map's EldoUI pin switch hides it with the other pins."] = "Метка на карте мира для каждого, кто выдает оставшиеся задания в зоне, показанной на карте. Наведите на нее, чтобы увидеть задания, нажмите, чтобы поставить путевую точку. Переключатель меток EldoUI на карте скрывает ее вместе с остальными метками.",
	["A pin where the next step of each attunement you are on starts. Click it for the arrow."] = "Метка там, где начинается следующий шаг каждого вашего допуска. Нажмите на нее, чтобы увидеть стрелку.",
	["A place in your journal"] = "Место в вашем дневнике",
	["a place to find"] = "место, которое нужно найти",
	["a profession you do not have"] = "профессия, которой у вас нет",
	["a quest"] = "задание",
	["A quest counts once you both have it and one of its objectives moves forward while you are grouped."] = "Задание засчитывается, когда оно есть у вас обоих и одна из его задач продвигается, пока вы в группе.",
	["A quest of this event."] = "Задание этого события.",
	["A quest outside dungeons, or a creature and what it drops."] = "Задание вне подземелий или существо и его добыча.",
	["A quest that needs this standing."] = "Задание, для которого нужна эта репутация.",
	["A quest that rewards the recipe."] = "Задание, наградой за которое служит рецепт.",
	["a racial spell; not modeled"] = "расовое заклинание; не моделируется",
	["a raid"] = "рейд",
	["A reached goal moves to the archive instead of staying in the Reached list."] = "Достигнутая цель уходит в архив, а не остается в списке «Достигнуто».",
	["A reminder"] = "Напоминание",
	["A sample step"] = "Пример шага",
	["A scroll above the name."] = "Свиток над именем.",
	["A scroll in a bronze frame above the name, to match the WoW Forever art style."] = "Свиток в бронзовой рамке над именем, в художественном стиле WoW Forever.",
	["A scroll, the quest giver's exclamation mark, a dot in your accent color, a scroll in a bronze frame, or a yellow square with a mark that reads for every kind of color blindness."] = "Свиток, восклицательный знак выдающего задание, точка вашего акцентного цвета, свиток в бронзовой рамке или желтый квадрат со знаком, который различим при любом виде дальтонизма.",
	["A short card when you enter a zone or a dungeon: your quests there, rares, your notes and your last run. Off in combat."] = "Короткая карточка при входе в зону или подземелье: ваши задания там, редкие существа, ваши заметки и последний заход. Выключено в бою.",
	["A short summary of the session during the logout countdown, also kept as a row in the Day view."] = "Краткая сводка сеанса во время обратного отсчета выхода, также сохраняется строкой в виде «День».",
	["A short tour of My Adventure."] = "Короткая экскурсия по «Моим приключениям».",
	["A small dot in your accent color left of the bar."] = "Маленькая точка вашего акцентного цвета слева от полосы.",
	["A small icon on the nameplate of a creature that can drop a quest starter. Needs EldoUI's Nameplates module."] = "Маленький значок на индикаторе здоровья существа, с которого может выпасть предмет, начинающий задание. Нужен модуль Nameplates в EldoUI.",
	["A small mark after each sentence; hover it to see the facts the sentence comes from."] = "Маленькая метка после каждого предложения; наведите на нее, чтобы увидеть факты, из которых оно составлено.",
	["A solid dark page with no ornaments, numbers first."] = "Однотонная темная страница без украшений, сначала числа.",
	["a spell"] = "заклинание",
	["A step of %s is here: %s."] = "Шаг «%s» здесь: %s.",
	["A step of %s is inside: %s."] = "Шаг «%s» внутри: %s.",
	["A string with this character's Best in Slot, plan sets, spec and talents (no name or realm) to share."] = "Строка с лучшими предметами (BiS), наборами плана, специализацией и талантами этого персонажа (без имени и мира), чтобы поделиться.",
	["A strip over the chapters with a mark for each level and its big moments. Click a level to open its chapter. Shown in the level view while no search or filter is on."] = "Полоса над главами с отметкой для каждого уровня и его важных моментов. Нажмите на уровень, чтобы открыть его главу. Видна в виде по уровням, пока нет поиска или фильтра.",
	["A to-do you check off yourself."] = "Дело, которое вы отмечаете сами.",
	["A toast or banner, a sound and a chat line when a wished item is in a loot window or a roll, or drops in the dungeon you enter. Set them in /eui > Loot Guide."] = "Всплывающее уведомление или баннер, звук и строка в чате, когда желанный предмет есть в окне добычи или в розыгрыше или выпадает в подземелье, куда вы входите. Настройка: /eui > Loot Guide.",
	["A toast when you finish a step or a whole attunement. Nothing is posted to chat."] = "Уведомление, когда вы завершаете шаг или весь допуск. В чат ничего не пишется.",
	["A trainer who teaches this recipe."] = "Наставник, который обучает этому рецепту.",
	["A vendor during this event."] = "Торговец во время этого события.",
	["A vendor for these rewards."] = "Торговец этими наградами.",
	["A vendor who sells the recipe."] = "Торговец, который продает рецепт.",
	["A yellow square with a mark above the name; the shape carries it too."] = "Желтый квадрат со знаком над именем; смысл передает и форма.",
	["A zone, or a spot inside one like Frostmane Hold."] = "Зона или место внутри нее, например Крепость Мерзлогривов.",
	["Abandoned"] = "Отменено",
	["Abandoned quests"] = "Отмененные задания",
	["Abandoned, failed, or removed by the game. The journal only lists them; nothing is picked up again for you."] = "Отмененные, проваленные или удаленные игрой. Дневник только перечисляет их; ничего не берется заново за вас.",
	["About %s of play at your recent pace. It counts your own last levels only."] = "Примерно %s игры в вашем недавнем темпе. Учитываются только ваши последние уровни.",
	["About %s per kill."] = "Примерно %s за убийство.",
	["About as good as what you wear"] = "Примерно так же хорошо, как надетое",
	["About the same"] = "Примерно то же",
	["About this zone"] = "Об этой зоне",
	["Above the name"] = "Над именем",
	["Accept merges it into this character's journal: nothing is lost, and a backup is taken first."] = "Принять — объединить с дневником этого персонажа: ничего не потеряется, а перед этим будет сделана резервная копия.",
	["account"] = "учетная запись",
	["Active goals"] = "Активные цели",
	["active now"] = "сейчас активно",
	["Active now"] = "Сейчас активно",
	["Active now and start dates: from the game's calendar."] = "Сейчас активно и даты начала: по игровому календарю.",
	["starts %s"] = "начнётся %s",
	["add it to the planner on the right"] = "добавить в планировщик справа",
	["Add my BiS"] = "Добавить мой BiS",
	["Add note"] = "Добавить заметку",
	["add or remove this from the filter"] = "добавить в фильтр или убрать из него",
	["add or remove this item"] = "добавить или убрать этот предмет",
	["Add to wishlist"] = "Добавить в список желаний",
	["Add wishlist note"] = "Добавить заметку к желанию",
	["Added %d best-in-slot items to your wishlist."] = "Добавлено предметов BiS в список желаний: %d.",
	["Added %d items to %s."] = { one = "%d предмет добавлен в %s.", few = "%d предмета добавлены в %s.", many = "%d предметов добавлено в %s.", other = "%d предмета добавлено в %s." },
	["Added %d pieces of %s to your wishlist."] = { one = "%d предмет из «%s» добавлен в список желаний.", few = "%d предмета из «%s» добавлены в список желаний.", many = "%d предметов из «%s» добавлено в список желаний.", other = "%d предмета из «%s» добавлено в список желаний." },
	["Added %d PvP items from your wishlist to the planner."] = "Добавлено в планировщик предметов PvP из списка желаний: %d.",
	["Added %s to %s."] = "%s добавлено в %s.",
	["Adds a button to the toast that posts one line in guild chat when you click it."] = "Добавляет к уведомлению кнопку, которая по нажатию пишет одну строку в чат гильдии.",
	["Adds a Need, Greed or Pass word to that box. It is a label only and never rolls for you."] = "Добавляет в это поле слово «Мне это нужно», «Не откажусь» или «Отказаться». Это лишь подпись, она никогда не бросает кубики за вас.",
	["Adds a Quests line (done of total) to Zone Info's world map tooltip when you hover a zone. Needs the Zone Info module."] = "Добавляет строку «Задания» (выполнено из всего) в подсказку карты мира Zone Info, когда вы наводите курсор на зону. Нужен модуль Zone Info.",
	["Adds it to your goals, so the tracker and the Goals page follow it."] = "Добавляет в ваши цели, чтобы трекер и страница «Цели» следили за ним.",
	["Adds the best-in-slot items for your spec that you do not own and have not wished for yet."] = "Добавляет лучшие предметы (BiS) для вашей специализации, которых у вас нет и которые вы еще не пожелали.",
	["Adds the item to your active wishlist, or takes it off every list on show."] = "Добавляет предмет в активный список желаний или убирает его из всех показанных списков.",
	["Adds the item to your active wishlist, or takes it off."] = "Добавляет предмет в активный список желаний или убирает его оттуда.",
	["Adds the PvP rewards on your active wishlist to the planner."] = "Добавляет в планировщик награды PvP из активного списка желаний.",
