	["EldoUI already knew %d moments of yours from its other records: they are on your Journey."] = { one = "EldoUI уже знал %d ваш момент из других своих записей: он в вашем «Пути».", few = "EldoUI уже знал %d ваших момента из других своих записей: они в вашем «Пути».", many = "EldoUI уже знал %d ваших моментов из других своих записей: они в вашем «Пути».", other = "EldoUI уже знал %d вашего момента из других своих записей: они в вашем «Пути»." },
