	["Ends the tour. Start it again with /eui tour journal."] = "Завершает экскурсию. Начните заново командой /eui tour journal.",
	["Ends the tour. Start it again with Start tour on the Loot Guide settings page or /eui tour lootguide."] = "Завершает экскурсию. Начните заново кнопкой «Начать экскурсию» на странице настроек Loot Guide или командой /eui tour lootguide.",
