	["Epic find"] = "Эпическая находка",
	["Epic finds and the wishlist items you got."] = "Эпические находки и полученные предметы из списка желаний.",
	["Epic finds come from bosses deep in dungeons, later in your journey."] = "Эпические находки падают с боссов в глубине подземелий, позже в вашем пути.",
	["Epic finds come from bosses. These dungeons fit your level:"] = "Эпические находки падают с боссов. Эти подземелья подходят вашему уровню:",
