	["Esc closes the window too."] = "Esc тоже закрывает окно.",
	["Essentials"] = "Главное",
	["estimate"] = "оценка",
	["Estimates from fights against a target dummy with your own character sheet and public Classic combat rules. Set bonuses and item procs are not counted."] = "Оценки по боям с тренировочным манекеном с вашим собственным листом персонажа и открытыми правилами боя Classic. Бонусы комплектов и срабатывания предметов не учитываются.",
	["Everlook"] = "Круговзор",
	["Every attunement and key step by step. Its next steps show up in Next trips and on Today."] = "Каждый допуск и ключ шаг за шагом. Следующие шаги появляются в «Следующих поездках» и в «Сегодня».",
	["Every attunement and key, step by step."] = "Каждый допуск и ключ, шаг за шагом.",
	["Every best-in-slot item is already yours or on your wishlist."] = "Все предметы BiS уже ваши или в списке желаний.",
	["Every craft per profession: what it makes, the skill it needs, the reagents you own and where the recipe comes from."] = "Каждое изготовление по профессиям: что получается, нужный навык, ваши материалы и откуда рецепт.",
	["Every dungeon and raid with its bosses, loot, drop chances and quests. Inside a dungeon the window opens on it."] = "Каждое подземелье и рейд с боссами, добычей, шансами и заданиями. Внутри подземелья окно открывается на нем.",
	["Every dungeon and raid: bosses, drops with chances, quests and what is an upgrade for you."] = "Каждое подземелье и рейд: боссы, добыча с шансами, задания и что для вас улучшение.",
	["Every flight master you speak to adds a flight path. These zones fit your level:"] = "Каждый распорядитель полетов, с которым вы говорите, добавляет маршрут. Эти зоны подходят вашему уровню:",
	["Every idea for where to go next, with filters."] = "Все идеи, куда отправиться дальше, с фильтрами.",
	["Every idea, best first, with filters for dungeons, quests, attunements, and zones, for your group and the time you have. Hover a card to see every reason; Not now puts it away until your next level."] = "Все идеи, лучшие сначала, с фильтрами по подземельям, заданиям, допускам и зонам, для вашей группы и вашего времени. Наведите на карточку, чтобы увидеть все причины; «Не сейчас» убирает ее до следующего уровня.",
	["Every item, creature, quest and place in sortable tables with filters and a detail panel."] = "Все предметы, существа, задания и места в сортируемых таблицах с фильтрами и панелью подробностей.",
	["Every item, mob, quest and vendor the loot data knows, with filters and sorting."] = "Все предметы, существа, задания и торговцы из данных о добыче, с фильтрами и сортировкой.",
	["Every keepsake, grouped by kind."] = "Все памятные моменты по видам.",
	["Every kind of result."] = "Все виды результатов.",
	["Every level is behind you"] = "Все уровни позади",
	["Every level is behind you. The journal keeps writing down your runs, finds, and standings."] = "Все уровни позади. Дневник продолжает записывать заходы, находки и репутацию.",
	["Every login"] = "При каждом входе",
	["Every Loot Guide page is switched off. Turn pages on in /eui > Loot Guide."] = "Все страницы Loot Guide выключены. Включите страницы в /eui > Loot Guide.",
	["Every moment."] = "Каждый момент.",
	["Every new standing"] = "Каждое новое отношение",
	["Every new standing, or Honored and up only. Changing it on a preset turns it into Custom."] = "Каждое новое отношение или только от «Уважения». Изменение в предустановке превращает ее в «Свое».",
	["Every part and chapter of the Book. Click one to turn to it."] = "Все части и главы «Книги». Нажмите, чтобы перейти.",
	["Every PvP reward with its cost and the rank or standing it needs, plus a planner for the weeks to afford them."] = "Все награды PvP с ценой и нужным званием или репутацией, плюс планировщик недель, чтобы их накопить.",
	["Every quest you handed in since the journal began, with where, when, and what it gave."] = "Каждое задание, сданное с начала дневника, с местом, временем и наградой.",
	["Every quest you handed in, with where, when, who gave it, and who came along; your quest log; and the quests the game remembers from before."] = "Каждое сданное задание: где, когда, кто выдал и кто был рядом; ваш журнал заданий; и задания, которые игра помнит с прошлого.",
	["Every run the Instances module recorded."] = "Каждый заход, записанный модулем «Подземелья».",
	["Every step for both sides and every class, also content the client does not list yet."] = "Каждый шаг для обеих сторон и каждого класса, включая контент, которого клиент еще не показывает.",
	["Every suggestion, best first."] = "Каждое предложение, лучшее сначала.",
	["Every time"] = "Каждый раз",
	["Every way to get one item."] = "Все способы получить один предмет.",
	["Every zone"] = "Каждая зона",
	["Every zone you visited, with its corners, time, kills, and quests, and every dungeon with its runs."] = "Каждая посещенная зона с уголками, временем, убийствами и заданиями, и каждое подземелье с заходами.",
	["Every zone's quests: how many you have done, what is left and who gives it, with a Map button for each giver."] = "Задания каждой зоны: сколько вы выполнили, что осталось и кто их выдает, с кнопкой «Карта» для каждого, кто выдает задания.",
	["Everyone"] = "Все",
	["Everyone falls sometime. There is no need to chase this one."] = "Все когда-то падают. За этим гнаться не нужно.",
	["Everyone falls sometime. There is no need to chase this one; here is what fits you instead:"] = "Все когда-то падают. За этим гнаться не нужно; вот что подходит вам вместо этого:",
	["Everyone you grouped with."] = "Все, с кем вы были в группе.",
	["Everything"] = "Все",
	["Everything is selected. Press Ctrl+C and share it. It holds your gear plans, spec and talents, not your name or realm."] = "Все выделено. Нажмите Ctrl+C и поделитесь. Здесь ваши планы экипировки, специализация и таланты, но не имя и мир.",
	["Everything is selected. Press Ctrl+C and share it. Others paste it into /eui import or the wishlist's Import."] = "Все выделено. Нажмите Ctrl+C и поделитесь. Другие вставят это в /eui import или в «Импорт» списка желаний.",
	["Everything reached. Start a new one with New goal."] = "Все достигнуто. Начните новую кнопкой «Новая цель».",
	["Everything you can get at your level is already as good as what you wear."] = "Все, что можно получить на вашем уровне, уже не лучше надетого.",
	["Everything, rare (blue) finds too, long chapters, every chapter open and a taller tracker."] = "Все, включая редкие (синие) находки, длинные главы, все главы открыты и трекер повыше.",
	["Exalted"] = "Превознесение",
	["Excavation Site"] = "Раскопки",
	["Exclamation mark"] = "Восклицательный знак",
	["Experience"] = "Опыт",
	["Experience and money next to each quest you handed in."] = "Опыт и деньги рядом с каждым сданным заданием.",
	["Explored %s"] = "Исследовано: %s",
	["Export"] = "Экспорт",
	["Export (share string)"] = "Экспорт (строка для обмена)",
	["Export a printable page"] = "Экспорт страницы для печати",
	["Export as Markdown"] = "Экспорт в Markdown",
	["Export as plain text"] = "Экспорт простым текстом",
	["Export formats: %s."] = "Форматы экспорта: %s.",
	["Faction"] = "Фракция",
	["Faction %d"] = "Фракция %d",
	["Factions that count you as Honored or better."] = "Фракции, у которых к вам «Уважение» или лучше.",
	["falls"] = "падения",
	["Fanfare's \"Journal moment\" triggers play or show with each moment. While such a trigger, or a level-up or boss-kill trigger, has a sound, the moment plays none of its own, so you hear one sound."] = "Триггеры «Момент журнала» из раздела «Fanfare» играют звук или показывают что-то при каждом моменте. Пока у такого триггера или у триггера повышения уровня или победы над боссом есть звук, момент не играет свой, чтобы вы слышали один звук.",
	["Farmed for %s"] = "Фарм: %s",
	["Fast (8 ms a frame)"] = "Быстро (8 мс на кадр)",
	["fastest"] = "быстрее всего",
	["Feet"] = "Ступни",
	["Fellowship"] = "Содружество",
	["Fewer"] = "Меньше",
	["Fiery Weapon"] = "Огненное оружие",
	["Lifestealing"] = "Похищение жизни",
	["Fight"] = "Бой",
	["Fighting"] = "В бою",
	["Fights against a target dummy with the best items of your list (one-minute fights, out of combat). Progress shows here, in the datatext and as a toast when done."] = "Бои с тренировочным манекеном с лучшими предметами вашего списка (бои по минуте, вне боя). Прогресс виден здесь, в инфотексте и в уведомлении по завершении.",
	["Fights against a target dummy with the best items of your list per slot: a quick pass, exact runs of the top picks, then the best set (one-minute fights, out of combat)."] = "Бои с тренировочным манекеном с лучшими предметами вашего списка по ячейкам: быстрый проход, точные прогоны лучших вариантов, затем лучший набор (бои по минуте, вне боя).",
	["Fights against a target dummy with this item instead of what you wear in its slot (about a second, out of combat). The result shows here, in the tooltip and as a toast."] = "Бои с тренировочным манекеном с этим предметом вместо надетого в эту ячейку (около секунды, вне боя). Результат виден здесь, в подсказке и в уведомлении.",
	["Fights against a target dummy with your own character sheet. Slower, but counts how your talents and spells use each stat. Items not simulated yet keep the weights gain."] = "Бои с тренировочным манекеном с вашим собственным листом персонажа. Медленнее, но учитывает, как ваши таланты и заклинания используют каждую характеристику. Еще не просчитанные предметы сохраняют выигрыш по весам.",
	["Fights against a target dummy with your own character sheet: DPS numbers for your gear, Best in Slot and plan sets. /eui sim opens its window."] = "Бои с тренировочным манекеном с вашим собственным листом персонажа: значения У/С для вашей экипировки, BiS и наборов плана. /eui sim открывает его окно.",
	["Fills an empty slot"] = "Заполняет пустую ячейку",
	["Fills the set with the Best in Slot items (the simulated set in Simulator mode)."] = "Заполняет набор предметами BiS (в режиме симулятора — просчитанным набором).",
	["Fills the set with your equipped gear."] = "Заполняет набор надетой экипировкой.",
	["Filter"] = "Фильтр",
	["Filter: %s · %s"] = "Фильтр: %s · %s",
	["Filter: pick your spec, the armor you wear and where your gear may come from. Every page and tooltip uses the same list."] = "Фильтр: выберите специализацию, носимую броню и откуда может быть ваша экипировка. Все страницы и подсказки используют один и тот же список.",
	["Filters for dungeons, quests, attunements, and zones."] = "Фильтры по подземельям, заданиям, допускам и зонам.",
	["Filters the crafts by the name of what they make."] = "Фильтрует изготовление по названию того, что получается.",
	["Filters the rewards and quests by name."] = "Фильтрует награды и задания по названию.",
	["Filters the rewards by name."] = "Фильтрует награды по названию.",
	["Filters the rows by item name and source."] = "Фильтрует строки по названию предмета и источнику.",
	["Find a group"] = "Найти группу",
	["Finds"] = "Находки",
	["Finds events by name."] = "Ищет события по названию.",
	["Finds from"] = "Находки из",
	["Finds sets and tokens by their name or a piece's name."] = "Ищет комплекты и жетоны по их названию или названию части.",
	["Finds, mounts, and companions."] = "Находки, транспорт и спутники.",
	["Finger"] = "Палец",
	["Finish %s"] = "Завершить: %s",
	["Finish %s."] = "Завершите: %s.",
	["Finish a quest"] = "Выполнить задание",
	["Finish an attunement"] = "Получить допуск",
	["Finished the chain with %s"] = "Цепочка завершена вместе с %s",
	["Fireball"] = "Огненный шар",
	["First %s."] = "Впервые: %s.",
	["First Aid"] = "Первая помощь",
	["First beaten %s · %d kills"] = { one = "Впервые побежден %s · %d убийство", few = "Впервые побежден %s · %d убийства", many = "Впервые побежден %s · %d убийств", other = "Впервые побежден %s · %d убийства" },
	["first boss kills"] = "первые победы над боссами",
