	["Notes show as pins on the world map and minimap where you wrote them, with the Map Notes switch. Needs the Map Notes module."] = "Заметки показываются метками на карте мира и миникарте там, где вы их написали, с переключателем «Заметки на карте». Нужен модуль «Заметки на карте».",
