	["Notes the quests, dungeons and zone level ranges the game shows you that the quest data does not know yet, so the quest pages can show them. Only what dialogs and the map show is read."] = "Записывает задания, подземелья и диапазоны уровней зон, которые показывает игра и которых еще нет в данных о заданиях, чтобы страницы заданий могли их показать. Читается только то, что показывают диалоги и карта.",
	["Notes written here"] = "Заметки, написанные здесь",
	["Notes you archive wait here until you restore or delete them."] = "Заметки, отправленные в архив, ждут здесь, пока вы их не восстановите или не удалите.",
	["Notes you archived. Restore or delete them there."] = "Заметки в архиве. Восстановите или удалите их там.",
	["Nothing changed: %s"] = "Ничего не изменилось: %s",
	["Nothing fits: turn on Higher levels, or install EldoUI_LootData for the full item list."] = "Ничего не подходит: включите «Более высокие уровни» или установите EldoUI_LootData для полного списка предметов.",
	["Nothing fits: widen the filter or turn on Higher levels."] = "Ничего не подходит: расширьте фильтр или включите «Более высокие уровни».",
	["Nothing found"] = "Ничего не найдено",
	["Nothing here fits your level."] = "Здесь ничего не подходит для вашего уровня.",
	["Nothing here is an upgrade for you now."] = "Здесь сейчас нет улучшений для вас.",
	["Nothing in progress."] = "Ничего не выполняется.",
	["Nothing in the Loot Guide matches %q."] = "В Loot Guide ничего не подходит под %q.",
	["Nothing in this group."] = "В этой группе ничего нет.",
	["Nothing is lost: it merges with what My Adventure has, a backup is taken first, and Undo puts it back. Forever Journal's own data is only read, never changed."] = "Ничего не теряется: данные объединяются с тем, что есть в «Моих приключениях», сначала делается резервная копия, а «Отменить» все вернет. Собственные данные Forever Journal только читаются и никогда не меняются.",
	["Nothing is waiting"] = "Ничего не ожидает",
	["Nothing matches"] = "Совпадений нет",
	["Nothing matches the filters."] = "Ничего не подходит под фильтры.",
	["No rewards match these filters."] = "Нет наград, подходящих под эти фильтры.",
	["Nothing new to report yet. The Journal notes the quests, dungeons, and zones the data does not know as you meet them."] = "Пока не о чем сообщить. Журнал записывает задания, подземелья и зоны, которых нет в данных, по мере того как вы их встречаете.",
	["Nothing of this kind right now"] = "Сейчас ничего такого нет",
