	["Numbered markers are the bosses, from the Classic data. Click one for its loot; click it again to close the list."] = "Пронумерованные метки — это боссы по данным Classic. Щелкните по метке, чтобы увидеть добычу; щелкните еще раз, чтобы закрыть список.",
	["Object"] = "Объект",
