	["Off"] = "Откл.",
	["off (turn on Mob and Loot Info)"] = "откл. (включите «Сведения о существах и добыче»)",
	["Off hand"] = "Левая рука",
	["Off-hand swings"] = "Удары левой рукой",
	["OK"] = "ОК",
	["on (Mob and Loot Info)"] = "вкл. («Сведения о существах и добыче»)",
	["On a character that gives, takes or is the target of an attunement step: which step and how far you are. Nothing shows when the game hides who it is."] = "На персонаже, который выдает, принимает шаг допуска или является его целью: какой шаг и насколько вы продвинулись. Ничего не показывается, когда игра скрывает, кто это.",
	["On a level-up the moment links to the dungeons, quests, spells and attunement steps that just opened."] = "При повышении уровня момент ссылается на подземелья, задания, заклинания и шаги допусков, которые только что открылись.",
	["On a quest link: when you took it or handed it in, at what level and where, and whether it is part of your next trip."] = "На ссылке на задание: когда вы его взяли или сдали, на каком уровне и где, и входит ли оно в вашу следующую поездку.",
	["On an item that is a step of an attunement: which one, whether you have it, and with Shift the next step."] = "На предмете, который является шагом допуска: какого, есть ли он у вас, и с Shift — следующий шаг.",
	["On an item:"] = "На предмете:",
	["On an item: when and where your journal saw you find it or put it on, and at what level."] = "На предмете: когда и где журнал видел, как вы его нашли или надели, и на каком уровне.",
	["on the quest"] = "по заданию",
