	["One kind, like Mottled Worg. Counts each one that gives you experience."] = "Один вид существ, с названием из игры. Считается каждое, которое дает вам опыт.",
	["One line for the tooltip."] = "Одна строка для подсказки.",
	["One line with the next thing that matters: a ready hand-in, trip prep or the next attunement step."] = "Одна строка со следующим важным делом: задание к сдаче, подготовка к поездке или следующий шаг допуска.",
