	["One step per row and finished attunements hidden: easy to read at a small window scale."] = "По шагу в строке, завершенные допуски скрыты: легко читать при малом масштабе окна.",
	["One step per row, in order. Easier to read at a small window scale."] = "По шагу в строке, по порядку. Легче читать при малом масштабе окна.",
