	["Open %s in Places"] = "Открыть %s в «Местах»",
	["Open a dungeon in the Journal and press Dungeon map: the floors with numbered boss markers. Entrance pins the way in on your world map."] = "Откройте подземелье в Журнале и нажмите «Карта подземелья»: этажи с пронумерованными метками боссов. «Вход» отмечает путь внутрь на карте мира.",
	["Open a quest or a creature from Search or an item page."] = "Откройте задание или существо через Поиск или со страницы предмета.",
