	["Opens a card that compares the item with what you wear, its source and your plans."] = "Открывает карточку, сравнивающую предмет с тем, что на вас надето, с его источником и вашими планами.",
	["Opens a copy box with the Forever quests you took, to send to EldoUI's authors so the dungeon can get a full chain."] = "Открывает поле для копирования со взятыми вами заданиями Forever, чтобы отправить их авторам EldoUI и у подземелья появилась полная цепочка.",
	["Opens a copy box with the list, to send to EldoUI's authors so the dungeon can get a full chain."] = "Открывает поле для копирования со списком, чтобы отправить его авторам EldoUI и у подземелья появилась полная цепочка.",
	["Opens EldoUI's keybind mode. My Adventure's keys (open or close it, quick note, the tracker, and Next trips) are also under Options > Keybindings > AddOns > EldoUI."] = "Открывает режим назначения клавиш EldoUI. Клавиши «Моих приключений» (открыть или закрыть, быстрая заметка, трекер и «Следующие поездки») также есть в «Параметры > Назначение клавиш > Модификации > EldoUI».",
	["Opens its page in the Journal."] = "Открывает его страницу в Журнале.",
	["Opens My Adventure in the Journal window."] = "Открывает «Мои приключения» в окне «Журнал».",
