	["Opens the boss in the Journal."] = "Открывает босса в Журнале.",
	["Opens the Catalog on Reputation: every faction and its rewards."] = "Открывает Каталог на «Репутации»: каждая фракция и ее награды.",
	["Opens the day you pick in the day view."] = "Открывает выбранный день в режиме дня.",
	["Opens the dungeon in the Journal on this creature."] = "Открывает подземелье в Журнале на этом существе.",
