	["Opens the dungeon's quest list on this quest."] = "Открывает список заданий подземелья на этом задании.",
	["Opens the Dungeons tab: every dungeon and raid with its bosses, loot and quests."] = "Открывает вкладку «Подземелья»: каждое подземелье и рейд с боссами, добычей и заданиями.",
	["Opens the game's group finder window. Nothing is listed or queued for you."] = "Открывает окно поиска группы игры. Ничего не размещается и не ставится в очередь за вас.",
	["Opens the instance in the Journal: bosses, loot and its quests."] = "Открывает подземелье в Журнале: боссы, добыча и его задания.",
	["Opens the item where it drops: the boss, the quest or the item page."] = "Открывает предмет там, где он падает: босс, задание или страница предмета.",
	["Opens the Journal window on My Adventure."] = "Открывает окно «Журнал» на «Моих приключениях».",
