	["Part of: %s (%d/%d)"] = "Часть: %s (%d/%d)",
	["Party"] = "Группа",
	["Party %d"] = "Группа %d",
	["Pass"] = "Отказаться",
	["Paste a journal backup code: !EUJ1! from EldoUI or FJ1: from Forever Journal. You see what it holds before anything changes."] = "Вставьте код резервной копии журнала: !EUJ1! из EldoUI или FJ1: из Forever Journal. Вы увидите содержимое до того, как что-то изменится.",
	["Paste a journal code"] = "Вставить код журнала",
	["Paste a wishlist string (Ctrl+V) and click Save."] = "Вставьте строку списка желаний (Ctrl+V) и нажмите «Сохранить».",
	["Paste it into a journal-data issue. It changes nothing in your game."] = "Вставьте его в отчет journal-data. В игре это ничего не меняет.",
	["paused for combat"] = "пауза из-за боя",
	["Paused for combat. The run goes on when combat ends."] = "Пауза из-за боя. Расчет продолжится, когда бой закончится.",
	["People"] = "Люди",
	["People you grouped with long enough for the journal to remember."] = "Люди, с которыми вы были в группе достаточно долго, чтобы журнал их запомнил.",
	["People you grouped with long enough for the journal to remember. Names show while Name companions is on."] = "Люди, с которыми вы были в группе достаточно долго, чтобы журнал их запомнил. Имена видны, пока включено «Называть спутников».",
	["Pet"] = "Питомец",
	["pet cooldowns are not modeled"] = "время восстановления способностей питомца не моделируется",
	["Pick a backup, then Merge (keeps everything since) or Replace (exactly as it was). Your journal is backed up first."] = "Выберите копию, затем «Объединить» (сохраняет все, что было после) или «Заменить» (в точности как было). Сначала создается резервная копия журнала.",
	["Pick a craft to see its reagents and where the recipe comes from."] = "Выберите рецепт, чтобы увидеть реагенты и откуда берется рецепт.",
	["Pick a craft: its reagents with what you own and where the recipe comes from, with Map buttons."] = "Выберите рецепт: реагенты с тем, что у вас есть, и откуда берется рецепт, с кнопками «Карта».",
	["Pick a faction on the left."] = "Выберите фракцию слева.",
	["Pick a level above the one you have."] = "Выберите уровень выше вашего.",
	["Pick a quest on the left to see its chain, objectives and rewards."] = "Выберите задание слева, чтобы увидеть цепочку, задачи и награды.",
	["Pick a row to see it here."] = "Выберите строку, чтобы увидеть ее здесь.",
	["Pick a zone"] = "Выберите зону",
	["Pick an attunement from the list, or type its name."] = "Выберите допуск из списка или введите его название.",
	["Pick an item from your wishlist."] = "Выберите предмет из списка желаний.",
	["pick one and open it in the Loot Guide"] = "выбрать один и открыть его в Loot Guide",
	["Pick the list the stars add to, show other lists, make, rename, share or delete lists."] = "Выберите список, в который добавляют звездочки, покажите другие списки, создайте, переименуйте, поделитесь или удалите списки.",
	["Pick the target dummy's level and the fight length. Bosses are three levels above you."] = "Выберите уровень тренировочного манекена и длительность боя. Боссы на три уровня выше вас.",
	["Pick up a quest and it shows here until you hand it in."] = "Возьмите задание, и оно будет здесь, пока вы его не сдадите.",
	["Pick up its quests before you go."] = "Возьмите его задания перед походом.",
	["Pick up: %s"] = "Взять: %s",
	["Pick what you want to work towards."] = "Выберите, к чему хотите стремиться.",
	["Picked up %s · %s ago"] = "Взято %s · %s назад",
	["Picked up %s · handed in %s · took %s"] = "Взято %s · сдано %s · заняло %s",
	["Picked up in %s"] = "Взято в %s",
	["Picks new wording for the whole Book. The facts don't change."] = "Подбирает новые формулировки для всей Книги. Факты не меняются.",
	["Picks new wording for the whole story. The facts don't change."] = "Подбирает новые формулировки для всей истории. Факты не меняются.",
	["Pin"] = "Закрепить",
	["Pin look"] = "Вид меток",
	["Pin new notes to the Journey"] = "Закреплять новые заметки на «Пути»",
	["Pin size"] = "Размер меток",
	["Pin to Journey"] = "Закрепить на «Пути»",
	["Pinned"] = "Закреплено",
	["pinned"] = "закреплено",
	["Pinned notes"] = "Закрепленные заметки",
	["Pins at dungeon and raid entrances on the world and zone maps, with the level range and your upgrades inside. Where the game draws its own entrance pin, ours steps aside, so no entrance shows twice."] = "Метки у входов в подземелья и рейды на картах мира и зон, с диапазоном уровней и вашими улучшениями внутри. Там, где игра рисует собственную метку входа, наша скрывается, чтобы вход не отображался дважды.",
	["Pins for the givers of quests you can pick up now."] = "Метки для тех, кто выдает задания, которые можно взять сейчас.",
	["Pins the biggest of %d camps on your map. Click again for the next one; after the last the pin goes away."] = { one = "Отмечает на карте самый большой из %d лагеря. Щелкните еще раз для следующего; после последнего метка исчезает.", few = "Отмечает на карте самый большой из %d лагерей. Щелкните еще раз для следующего; после последнего метка исчезает.", many = "Отмечает на карте самый большой из %d лагерей. Щелкните еще раз для следующего; после последнего метка исчезает.", other = "Отмечает на карте самый большой из %d лагеря. Щелкните еще раз для следующего; после последнего метка исчезает." },
	["Pins the dungeon's entrance on your map."] = "Отмечает на карте вход в подземелье.",
	["Pins the entrance in %s on your map and turns on the arrow."] = "Отмечает на карте вход в зоне %s и включает стрелку.",
	["Pins the entrance on your map and opens the map there (out of combat)."] = "Отмечает вход на карте и открывает там карту (вне боя).",
	["Pins the entrance on your map."] = "Отмечает вход на карте.",
	["Pins the instance entrance on your map and turns on the arrow."] = "Отмечает на карте вход в подземелье и включает стрелку.",
	["Pins the instance entrance on your map, turns on the arrow and opens the map there (out of combat)."] = "Отмечает на карте вход в подземелье, включает стрелку и открывает там карту (вне боя).",
	["Pins the place on your map and turns on the arrow."] = "Отмечает место на карте и включает стрелку.",
	["Pins the place on your map and turns on the arrow. Click again to take the pin away."] = "Отмечает место на карте и включает стрелку. Щелкните еще раз, чтобы убрать метку.",
	["Place"] = "Место",
	["Places"] = "Места",
	["Places the boss markers by where the creatures stand in the Classic data, on a plain grid. Approximate: walls and floors are not drawn."] = "Размещает метки боссов там, где стоят существа по данным Classic, на простой сетке. Приблизительно: стены и полы не рисуются.",
	["Plan"] = "План",
	["Plan pieces to see the total and how many weeks of your recent honor each one takes."] = "Запланируйте вещи, чтобы увидеть сумму и сколько недель вашей недавней чести занимает каждая.",
	["Plan set"] = "Комплект плана",
	["Plan set %d"] = "Комплект плана %d",
	["Plan the trip"] = "Спланировать поездку",
	["Planned"] = "Запланировано",
	["Planner"] = "Планировщик",
