	["Play when game effects are muted"] = "Играть, когда звуки игры выключены",
	["played"] = "в игре",
	["Played for %s"] = "В игре: %s",
	["Player notes"] = "Заметки об игроках",
	["Plays moment sounds on the Master channel."] = "Воспроизводит звуки моментов в общем канале.",
	["Plays with the toast for a finished attunement. Step toasts are silent."] = "Звучит вместе с уведомлением о завершенном допуске. Уведомления о шагах беззвучны.",
	["Plays with this kind of moment. None: the card stays quiet."] = "Звучит при таком моменте. «Нет»: карточка остается беззвучной.",
	["Poison"] = "Яд",
	["Poor"] = "Низкое",
	["Poor (gray)"] = "Низкое (серое)",
	["Posts one line in guild chat."] = "Пишет одну строку в чат гильдии.",
	["Press %s to take a screenshot. Click or press Esc to close."] = "Нажмите %s, чтобы сделать снимок экрана. Щелкните или нажмите Esc, чтобы закрыть.",
	["Press Ctrl+C to copy it, save it as a .html file and open it in a browser. Print it to PDF for a keepsake."] = "Нажмите Ctrl+C, чтобы скопировать, сохраните как файл .html и откройте в браузере. Распечатайте в PDF на память.",
	["Press Ctrl+C to copy it, then paste it anywhere."] = "Нажмите Ctrl+C, чтобы скопировать, и вставьте куда угодно.",
	["Press Ctrl+C to copy it, then paste it into any Markdown editor or note app."] = "Нажмите Ctrl+C, чтобы скопировать, и вставьте в любой редактор Markdown или приложение для заметок.",
	["Press Ctrl+C to copy the code. Use \"Paste a journal code\" on this PC or another to restore the journal. Nothing is sent anywhere."] = "Нажмите Ctrl+C, чтобы скопировать код. Используйте «Вставить код журнала» на этом или другом ПК, чтобы восстановить журнал. Ничего никуда не отправляется.",
	["Press Ctrl+C to copy. Nothing is sent anywhere: paste it where you like."] = "Нажмите Ctrl+C, чтобы скопировать. Ничего никуда не отправляется: вставьте куда хотите.",
	["Press Ctrl+C to copy. Paste it back in with Paste a journal code, on this PC or another. Nothing is sent anywhere."] = "Нажмите Ctrl+C, чтобы скопировать. Вставьте обратно через «Вставить код журнала» на этом или другом ПК. Ничего никуда не отправляется.",
	["Press Sim to compare the checked sets in the same fights."] = "Нажмите «Сим», чтобы сравнить отмеченные комплекты в одинаковых боях.",
	["Press Sim to read your character and fight a target dummy 120 times. It takes a few seconds and runs out of combat."] = "Нажмите «Сим», чтобы считать персонажа и сразиться с тренировочным манекеном 120 раз. Это занимает несколько секунд и выполняется вне боя.",
	["Previous pages"] = "Предыдущие страницы",
	["Prints where the loot data comes from (same as /lg data)."] = "Выводит, откуда взяты данные о добыче (то же, что /lg data).",
	["Prints where the loot data comes from, its version and size (same as /lg data)."] = "Выводит, откуда взяты данные о добыче, их версию и размер (то же, что /lg data).",
	["profession"] = "профессия",
	["Profession mastered"] = "Профессия освоена",
	["Profession needed"] = "Нужна профессия",
	["Protection: Shield Slam and Sunder Armor"] = "Защита: Мощный удар щитом и Раскол брони",
	["Providers:"] = "Поставщики:",
	["Put away (%d)"] = "Отложено (%d)",
	["Put away until your next break."] = "Отложено до вашего следующего перерыва.",
	["Put away until your next level or for 24 hours."] = "Отложено до следующего уровня или на 24 часа.",
	["Put in %s"] = "Поместить в %s",
	["Put in chat"] = "В чат",
	["put it in the chat box"] = "вставить в строку чата",
	["Put on %s"] = "Надето: %s",
	["Put on %s in %s"] = "Надето: %s, %s",
	["Puts a group line into the chat box. Nothing is sent until you press Enter."] = "Помещает строку для группы в поле чата. Ничего не отправляется, пока вы не нажмете Enter.",
	["Puts every journal the last import touched back as it was before, and its settings too."] = "Возвращает каждый журнал, затронутый последним импортом, к прежнему виду, вместе с настройками.",
	["Puts every piece you do not have on your active wishlist."] = "Добавляет все недостающие вам вещи в активный список желаний.",
	["Puts its quests that are already in your log on the objective tracker. Nothing is accepted for you."] = "Добавляет в список целей его задания, которые уже есть в вашем журнале. Ничего не принимается за вас.",
	["Puts one line about your character in the chat box. You read it and press Enter to send it."] = "Помещает строку о вашем персонаже в поле чата. Вы читаете ее и нажимаете Enter, чтобы отправить.",
	["Puts the item in this plan set on the Best in Slot page, or takes it out. Plan sets are plans, not equipment sets."] = "Помещает предмет в этот комплект плана на странице Best in Slot или убирает его. Комплекты плана — это планы, а не комплекты экипировки.",
	["Puts the item link into the chat line you are typing in."] = "Вставляет ссылку на предмет в строку чата, которую вы набираете.",
	["Puts the window back at the top of the screen at normal size."] = "Возвращает окно наверх экрана в обычном размере.",
	["Puts this card away until your next break."] = "Откладывает эту карточку до вашего следующего перерыва.",
	["Puts this card away until your next level or for 24 hours."] = "Откладывает эту карточку до следующего уровня или на 24 часа.",
	["Puts this card away."] = "Откладывает эту карточку.",
