	["Show steps for"] = "Показать шаги для",
	["Show the %s page in the Loot Guide window."] = "Показывать страницу «%s» в окне Loot Guide.",
	["Show the %s page in the Loot Guide window. Hiding it also hides gain marks in lists and plan sets in tooltips."] = "Показывать страницу «%s» в окне Loot Guide. Это также скрывает метки выигрыша в списках и наборы плана в подсказках.",
	["Show the %s page in the Loot Guide window. Hiding it also hides the wishlist stars and tooltip line."] = "Показывать страницу «%s» в окне Loot Guide. Это также скрывает звезды списка желаний и строку подсказки.",
	["Show the quests in progress"] = "Показать задания в процессе",
	["Show the story"] = "Показать историю",
	["Show them as they happen, or hold them and show one summary when you leave."] = "Показывать по мере появления или копить и показать одну сводку при выходе.",
	["Show what this token buys"] = "Показать, что дает этот жетон",
	["Showing the first %d items. Type more to narrow it down."] = "Показаны первые %d предметов. Введите больше, чтобы сузить поиск.",
	["Shown here and used for upgrades when Rate items by is Simulator. Estimates: set bonuses and item procs are not counted."] = "Показывается здесь и используется для улучшений, когда «Оценивать предметы по» — симулятор. Оценки: бонусы комплектов и срабатывающие эффекты предметов не учитываются.",
	["Shows a level moment the way it looks with your settings."] = "Показывает момент уровня так, как он выглядит с вашими настройками.",
	["Shows a sample alert with your settings."] = "Показывает пример оповещения с вашими настройками.",
	["Shows a sample toast with your settings."] = "Показывает пример уведомления с вашими настройками.",
	["Shows an item tooltip with the Loot Guide lines, so you can see your settings."] = "Показывает подсказку предмета со строками Loot Guide, чтобы вы видели свои настройки.",
	["Shows both factions, every class and content the game does not list yet."] = "Показывает обе фракции, все классы и контент, которого игра еще не перечисляет.",
	["Shows every drop of this rare."] = "Показывает всю добычу этого редкого противника.",
	["Shows every kind."] = "Показывает все виды.",
	["Shows every piece on your character in the dressing room."] = "Показывает каждую вещь на вашем персонаже в примерочной.",
	["Shows every place again."] = "Снова показывает все места.",
	["Shows gain marks, plan sets and upgrades again."] = "Снова показывает отметки прироста, комплекты плана и улучшения.",
	["Shows how much the item would gain you beside each loot roll. Advice only: you always roll yourself."] = "Показывает рядом с каждым розыгрышем добычи, сколько вам дал бы предмет. Только совет: бросаете вы всегда сами.",
	["Shows on the Attunements tab how many attunements, steps and quests are loaded and the data version."] = "Показывает на вкладке «Допуски», сколько загружено допусков, шагов и заданий, и версию данных.",
	["Shows only instances within the level window of yours (Loot Guide settings)."] = "Показывает только подземелья в пределах вашего окна уровней (настройки Loot Guide).",
	["Shows only items that beat what you wear, rated by the shared item engine."] = "Показывает только предметы лучше надетых, по оценке общего механизма предметов.",
	["Shows only rares and creatures that drop an upgrade for you."] = "Показывает только редких противников и существ, с которых падает улучшение для вас.",
	["Shows only rewards that beat what you wear."] = "Показывает только награды лучше надетого.",
	["Shows only this armor kind. Click again for all."] = "Показывает только этот тип доспехов. Щелкните еще раз для всех.",
	["Shows that attunement."] = "Показывает этот допуск.",
