	["Switches the Alts module on. Each character is added the next time you log in on it."] = "Включает модуль «Персонажи». Каждый персонаж добавляется при следующем входе за него.",
	["Switches the Loot Guide module on; My Adventure comes with it."] = "Включает модуль Loot Guide; «Мои приключения» включаются вместе с ним.",
	["Switches the Loot Guide module on; quest starter hints come with it."] = "Включает модуль Loot Guide; подсказки о предметах, начинающих задания, идут вместе с ним.",
	["Switches the Loot Guide module on; the Attunements tab comes with it."] = "Включает модуль Loot Guide; вкладка «Допуски» включается вместе с ним.",
	["Switches the Loot Guide module on; the Zones section comes with it."] = "Включает модуль Loot Guide; раздел «Зоны» идет вместе с ним.",
	["Switches the table. Each table keeps its search and filters for this session."] = "Переключает таблицу. Каждая таблица сохраняет свой поиск и фильтры на этот сеанс.",
	["Tabard"] = "Гербовая накидка",
	["Tabards"] = "Гербовые накидки",
	["Tailoring"] = "Портняжное дело",
	["Take a screenshot"] = "Сделать снимок экрана",
	["Take a screenshot with your screenshot key. Click or press Esc to close."] = "Сделайте снимок экрана своей клавишей. Щелкните или нажмите Esc, чтобы закрыть.",
	["take it out of the planner"] = "убрать из планировщика",
	["Take the tour"] = "Пройти обзор",
	["Taken"] = "Взято",
	["Taken at %s. You find it in the Screenshots folder of your game."] = "Сделан в %s. Его можно найти в папке Screenshots вашей игры.",
	["taken before the journal kept track"] = "взято до того, как журнал начал вести записи",
	["Taken before the journal kept track."] = "Взято до того, как журнал начал вести записи.",
	["Taken off your keepsakes."] = "Убрано из памятного.",
	["Takes a backup of this journal now."] = "Создает резервную копию этого журнала сейчас.",
	["Takes about %d minutes."] = { one = "Занимает около %d минуты.", few = "Занимает около %d минут.", many = "Занимает около %d минут.", other = "Занимает около %d минуты." },
	["Takes it off your keepsakes."] = "Убирает из памятного.",
	["Takes one screenshot of the card, without this button and the hint. It goes to the Screenshots folder of your game."] = "Делает один снимок карточки без этой кнопки и подсказки. Он сохраняется в папку Screenshots вашей игры.",
	["Takes step %d: %s"] = "Принимает шаг %d: %s",
	["Takes this note off your Journey."] = "Убирает эту заметку с «Пути».",
	["Taking it with you"] = "Взять с собой",
	["Talents are read by name, which works on English game clients only. On this client the simulator plays without talent effects."] = "Таланты определяются по названию, что работает только в английских клиентах игры. В этом клиенте симулятор играет без эффектов талантов.",
	["Talents the simulator plays"] = "Таланты, которые учитывает симулятор",
	["Tank"] = "Танк",
	["Tank: avoidance pick (%s holds more threat)"] = "Танк: выбор ради избегания (%s дает больше угрозы)",
	["Tank: close call with %s"] = "Танк: почти вровень с %s",
	["Tank: threat pick (%s holds more avoidance)"] = "Танк: выбор ради угрозы (%s дает больше избегания)",
	["Target"] = "Цель",
	["target level %d"] = "уровень цели %d",
	["Teaches"] = "Обучает",
	["Tell the guild"] = "Сказать гильдии",
	["Tell the guild button"] = "Кнопка «Сказать гильдии»",
	["Telling"] = "Отправка",
	["Tells you when a wishlist item is in a loot window or a roll, or drops in the dungeon you enter. It never loots or rolls for you."] = "Сообщает, когда предмет из списка желаний оказывается в окне добычи или розыгрыше или падает в подземелье, куда вы входите. Никогда не собирает добычу и не бросает кости за вас.",
	["Test alert"] = "Тестовое оповещение",
	["Text size of the story in the Book and Story so far, 90 to 140%."] = "Размер текста рассказа в Книге и «Истории на сегодня», от 90 до 140 %.",
	["That backup is gone."] = "Этой резервной копии больше нет.",
	["That dungeon is not in the dungeon list."] = "Этого подземелья нет в списке подземелий.",
	["That goal could not be set."] = "Не удалось поставить эту цель.",
	["That is not a Forever Journal backup code (it starts with FJ1:)."] = "Это не код резервной копии Forever Journal (он начинается с FJ1:).",
	["That is not a journal code. A journal code starts with !EUJ1! (EldoUI) or FJ1: (Forever Journal)."] = "Это не код журнала. Код журнала начинается с !EUJ1! (EldoUI) или FJ1: (Forever Journal).",
	["That is one of your goals already."] = "Это уже одна из ваших целей.",
	["That item does not go in an equipment slot."] = "Этот предмет не надевается ни в одну ячейку экипировки.",
	["That item does not go in this slot."] = "Этот предмет не подходит для этой ячейки.",
	["That quest chain is not in the quest data."] = "Этой цепочки нет в данных о заданиях.",
	["The %s page is switched off on the Loot Guide settings page."] = "Страница «%s» отключена на странице настроек Loot Guide.",
	["the address to report problems"] = "адрес для сообщений о проблемах",
	["The adventurer's log: plain past tense, places and levels first."] = "Журнал искателя приключений: простое прошедшее время, сначала места и уровни.",
	["The Alts module stays off while %s is loaded, so only this character is known."] = "Модуль «Персонажи» остается выключенным, пока загружен %s, поэтому известен только этот персонаж.",
	["The Argent Dawn sends you to Naxxramas once you are Honored or better; each rank makes the way in cheaper."] = "Серебряный Рассвет отправит вас в Наксрамас, как только вы достигнете уважения или выше; каждый ранг удешевляет вход.",
	["The Attunements tab lives in the Loot Guide. Turn the Loot Guide on first."] = "Вкладка «Допуски» находится в Loot Guide. Сначала включите Loot Guide.",
	["The Attunements tab lives in the Loot Guide. Turn the Loot Guide on to use it."] = "Вкладка «Допуски» находится в Loot Guide. Включите Loot Guide, чтобы ею пользоваться.",
	["The backup is merged into your journal."] = "Резервная копия объединяется с вашим журналом.",
	["The best gear you can get for your spec and level, your filter and stat order, and two plan sets of your own."] = "Лучшая экипировка, доступная для вашей специализации и уровня, ваш фильтр и порядок характеристик и два собственных комплекта плана.",
	["The best idea for right now and why it is here. A dungeon opens as a trip plan: the quests to pick up first, getting in, inside, and afterwards. Every button only shows you the way."] = "Лучшая идея на сейчас и почему она здесь. Подземелье открывается как план поездки: задания, которые нужно взять заранее, путь внутрь, внутри и после. Каждая кнопка только показывает путь.",
	["The best item per slot from your list, what you wear, your two plan sets and your wishlist by slot. Click a slot to pick something else."] = "Лучший предмет на ячейку из вашего списка, надетое, ваши два комплекта плана и список желаний по ячейкам. Щелкните ячейку, чтобы выбрать что-то другое.",
	["The best items on your list for your spec and the plan phase, one per slot. The number is the gain over what you wear."] = "Лучшие предметы из вашего списка для вашей специализации и фазы плана, по одному на ячейку. Число — прирост относительно надетого.",
	["The card joins the suggestions again."] = "Карточка снова среди предложений.",
	["The cards you put away. They come back at your next level or after 24 hours."] = "Отложенные вами карточки. Они вернутся на следующем уровне или через 24 часа.",
	["The cards you sent off with Not now, with Bring back."] = "Карточки, отправленные кнопкой «Не сейчас», с кнопкой «Вернуть».",
	["The cards you sent off with Not now."] = "Карточки, отправленные кнопкой «Не сейчас».",
	["The chain as a chart: every step a box, lines to the steps that need it."] = "Цепочка схемой: каждый шаг в рамке, линии к шагам, которым он нужен.",
	["The check could not start."] = "Не удалось начать проверку.",
	["The check is running: %d of %d quests asked. %s stops it."] = { one = "Идет проверка: опрошено %d из %d задания. %s останавливает ее.", few = "Идет проверка: опрошено %d из %d заданий. %s останавливает ее.", many = "Идет проверка: опрошено %d из %d заданий. %s останавливает ее.", other = "Идет проверка: опрошено %d из %d задания. %s останавливает ее." },
	["The client does not know where this entrance is."] = "Клиент не знает, где этот вход.",
	["The code is incomplete or damaged (%s). Copy all of it and paste it again."] = "Код неполный или поврежден (%s). Скопируйте его целиком и вставьте снова.",
	["The code is incomplete or damaged. Copy all of it and paste it again."] = "Код неполный или поврежден. Скопируйте его целиком и вставьте снова.",
	["The code is incomplete or damaged. Copy all of it, from FJ1: to the last }."] = "Код неполный или поврежден. Скопируйте его целиком, от FJ1: до последней }.",
	["The commands and the address for problems. Pages, drop chances, the rating mode, alerts and the window look are in /eui > Loot Guide."] = "Команды и адрес для сообщений о проблемах. Страницы, шансы добычи, режим оценки, оповещения и вид окна — в /eui > Loot Guide.",
	["The Crescent Key opens the doors of Dire Maul West and North; a boss in Dire Maul East drops it."] = "Ключ-полумесяц открывает двери Забытого города (запад и север); его роняет босс в восточной части Забытого города.",
	["The data has no place on your map for this quest's giver."] = "В данных нет места на вашей карте для того, кто выдает это задание.",
	["The database needs the loot data"] = "Базе данных нужны данные о добыче",
	["The Defilers"] = "Осквернители",
	["the details"] = "подробности",
	["the details below"] = "подробности ниже",
	["The door opens at level %d."] = "Дверь открывается с %d-го уровня.",
	["The drop data comes with the Loot Guide. Turn the Loot Guide on to use it."] = "Данные о добыче поставляются с Loot Guide. Включите Loot Guide, чтобы ими пользоваться.",
	["The Drowned City"] = "The Drowned City",
	["the dummy cannot be stunned in a useful way"] = "манекен нельзя с пользой оглушить",
	["the dummy does not hit back"] = "манекен не бьет в ответ",
	["the dungeon"] = "подземелье",
	["The EldoUI page and the place to report problems. Copy (Ctrl+C) and open them in your browser."] = "Страница EldoUI и место для сообщений о проблемах. Скопируйте (Ctrl+C) и откройте в браузере.",
	["The EldoUI project page and the address to report a wrong drop or a problem, ready to copy."] = "Страница проекта EldoUI и адрес, чтобы сообщить о неверной добыче или проблеме, готовые к копированию.",
	["The entrance is %s."] = "Вход находится %s.",
	["The Exodar"] = "Экзодар",
	["The export did not work. The error is in the error list."] = "Экспорт не удался. Ошибка — в списке ошибок.",
	["The filters hide every answer."] = "Фильтры скрывают все ответы.",
	["The first faction that counts you as Honored."] = "Первая фракция, у которой вы достигли уважения.",
	["The first flight path you learned."] = "Первый изученный вами маршрут полета.",
	["The first one on %s. Take its items or money from a mailbox."] = "Первое истекает %s. Заберите вложения или деньги из почтового ящика.",
	["The first page is still blank"] = "Первая страница еще пуста",
	["The first quest you handed in with a group."] = "Первое задание, сданное вами в группе.",
	["The first rare you saw."] = "Первый увиденный вами редкий противник.",
	["The first step is open: %s."] = "Первый шаг открыт: %s.",
	["The first time you died. It happens to everyone."] = "Ваша первая смерть. Это случается со всеми.",
	["The first time you entered a dungeon."] = "Первый раз, когда вы вошли в подземелье.",
	["The first time you entered a raid."] = "Первый раз, когда вы вошли в рейд.",
	["The game could not save it. Try your own screenshot key."] = "Игре не удалось его сохранить. Попробуйте свою клавишу снимка экрана.",
	["The game did not show your weapon skill, so the simulator used the usual skill for your level (5 per level)."] = "Игра не показала ваш навык владения оружием, поэтому симулятор взял обычный навык для вашего уровня (5 за уровень).",
	["The game does not list that faction for you yet. Check the spelling on your Reputation tab."] = "Игра пока не показывает вам эту фракцию. Проверьте написание на вкладке «Репутация».",
	["The game does not list this dungeon yet. It shows here as soon as it does."] = "Игра пока не перечисляет это подземелье. Оно появится здесь, как только это произойдет.",
	["The game does not report this step; it counts once the next one is done."] = "Игра не сообщает об этом шаге; он засчитывается, когда выполнен следующий.",
	["The game does not tell where this entrance is."] = "Игра не сообщает, где этот вход.",
	["The game has no map picture for this place. Here are its bosses in order; click one for its loot."] = "У игры нет изображения карты для этого места. Вот его боссы по порядку; щелкните по боссу, чтобы увидеть добычу.",
	["The game has no name for that place yet."] = "У игры пока нет названия для этого места.",
	["The game has not sent this item's stats yet."] = "Игра еще не прислала характеристики этого предмета.",
	["the game marks it done"] = "игра отмечает его выполненным",
	["The game remembers %s quests you finished before the journal began."] = { one = "Игра помнит %s задание, выполненное до начала журнала.", few = "Игра помнит %s задания, выполненных до начала журнала.", many = "Игра помнит %s заданий, выполненных до начала журнала.", other = "Игра помнит %s задания, выполненных до начала журнала." },
	["the game remembers it as done"] = "игра помнит его выполненным",
	["The game shows this rare on your minimap right now."] = "Игра сейчас показывает этого редкого противника на миникарте.",
	["The game's map could not place any creature camp. Open the world map once and come back."] = "Карте игры не удалось разместить ни одного лагеря существ. Откройте карту мира один раз и вернитесь.",
	["The game's map says you are in this zone."] = "По карте игры вы в этой зоне.",
	["The game's own count of quests you completed."] = "Собственный счетчик игры выполненных вами заданий.",
	["The game's own count of your deaths."] = "Собственный счетчик игры ваших смертей.",
	["The gear you wear; each slot shows how much its Best in Slot item adds."] = "Надетая экипировка; каждая ячейка показывает, сколько добавит ее предмет Best in Slot.",
	["The group finder could not open here."] = "Здесь не удалось открыть поиск группы.",
	["The group finder opens after combat."] = "Поиск группы откроется после боя.",
	["The guide goes back to following your zone when your map changes."] = "Справочник снова следует за вашей зоной, когда меняется карта.",
	["The guide needs the loot data (the EldoUI_LootData addon) or the game's dungeon finder list to suggest trips."] = "Чтобы предлагать поездки, путеводителю нужны данные о добыче (модификация EldoUI_LootData) или список поиска подземелий игры.",
	["The guide needs the loot data (the EldoUI_LootData addon) or the game's dungeon finder list to suggest trips. Quests in your log still show here."] = "Чтобы предлагать поездки, путеводителю нужны данные о добыче (модификация EldoUI_LootData) или список поиска подземелий игры. Задания из журнала все равно показываются здесь.",
	["The Hall of Thanes"] = "The Hall of Thanes",
	["The honor cost and PvP rank the item needs."] = "Стоимость в чести и PvP-звание, нужные для предмета.",
	["The import is undone."] = "Импорт отменен.",
	["The instance page with every boss, its quests and its trash loot."] = "Страница подземелья с каждым боссом, его заданиями и добычей с обычных противников.",
	["The item; its color is its quality."] = "Предмет; его цвет — его качество.",
	["the items that fit this slot"] = "предметы для этой ячейки",
	["The items you see this boss drop are added here."] = "Предметы, выпадение которых с этого босса вы видите, добавляются сюда.",
	["The journal as a readable document, by chapter, with goals, notes and quests. Companion names are left out."] = "Журнал в виде удобного для чтения документа, по главам, с целями, заметками и заданиями. Имена спутников не включаются.",
	["The journal as a web page (HTML). Save it as a .html file, open it in a browser and print it to PDF. Opened outside the game it loads its fonts from Google Fonts."] = "Журнал в виде веб-страницы (HTML). Сохраните его как файл .html, откройте в браузере и распечатайте в PDF. Открытый вне игры, он загружает шрифты с Google Fonts.",
	["The journal as plain text, by chapter."] = "Журнал простым текстом, по главам.",
	["The journal begins in %s"] = "Журнал начинается: %s",
	["The journal has no company by that name."] = "В журнале нет никого с таким именем.",
	["The journal has not been here yet."] = "Журнал здесь еще не бывал.",
	["The journal is not ready yet. Try again in a moment."] = "Журнал еще не готов. Попробуйте через мгновение.",
	["The journal of %s, saved %s."] = "Журнал персонажа %s, сохранен %s.",
	["The journal shows what the game and your other EldoUI modules wrote down. Nothing is guessed."] = "Журнал показывает то, что записали игра и другие ваши модули EldoUI. Ничего не угадывается.",
	["The journal waits for the end of combat"] = "Журнал ждет окончания боя",
	["The Journal window's dark page and the EldoUI Book, the Storyteller detail with keepsakes, the tracker under your quests and moments in the alert lane."] = "Темная страница окна «Журнал» и Книга EldoUI, детальность «Рассказчик» с памятным, трекер под заданиями и моменты в полосе оповещений.",
	["The Journal window's own dark page with the accent color."] = "Собственная темная страница окна «Журнал» с цветом акцента.",
	["The journal's own rows: short, exact, with digits."] = "Собственные строки журнала: коротко, точно, цифрами.",
	["The journal's pages are switched off or still loading."] = "Страницы журнала отключены или еще загружаются.",
	["The Journey's day view on the day you last played."] = "Режим дня «Пути» на день, когда вы играли в последний раз.",
	["The Key to the City opens the service gate of Stratholme; a boss inside drops it."] = "Ключ от города открывает служебные ворота Стратхольма; его роняет босс внутри.",
	["The last one you had open"] = "Последний открытый",
	["The last run is outdated: your level, gear, talents or list changed."] = "Последний расчет устарел: изменились ваш уровень, экипировка, таланты или список.",
	["The League of Arathor"] = "Лига Аратора",
	["The level log was off for these levels."] = "История уровней для этих уровней была выключена.",
	["The level of the target dummy. Bosses are three levels above you: more misses, glancing blows and resists."] = "Уровень тренировочного манекена. Боссы на три уровня выше вас: больше промахов, скользящих ударов и сопротивлений.",
	["The light part is rested experience: kills give double experience until it is used up."] = "Светлая часть — бонусный опыт за отдых: убийства дают вдвое больше опыта, пока он не израсходован.",
	["The line is in the chat box. Press Enter to send it, or Escape to drop it."] = "Строка в поле чата. Нажмите Enter, чтобы отправить, или Esc, чтобы отменить.",
	["The list on the left leaves out attunements you have finished."] = "Список слева не показывает завершенные вами допуски.",
	["The long chain of Anachronos and the three dragonflights that opens the gates of Ahn'Qiraj."] = "Длинная цепочка Анахроноса и трех стай драконов, открывающая врата Ан'Киража.",
	["The long chain through Stormwind and Blackrock Spire ends with the Drakefire Amulet you need for Onyxia's Lair."] = "Длинная цепочка через Штормград и пик Черной горы заканчивается Амулетом Драконьего Огня, нужным для Логова Ониксии.",
	["the loot"] = "добыча",
	["The loot data does not list where this recipe comes from."] = "Данные о добыче не говорят, откуда этот рецепт.",
	["The loot data has no place on your map for this."] = "В данных о добыче нет места на карте для этого.",
	["The loot data has no rares or named creatures for the zone you are in. Pick a zone on the left."] = "В данных о добыче нет редких или именных существ для вашей зоны. Выберите зону слева.",
	["The loot data lists no bosses here."] = "Данные о добыче не содержат боссов здесь.",
	["The loot data lists no crafts for this profession."] = "Данные о добыче не содержат рецептов этой профессии.",
	["The loot data lists no factions for your side."] = "В данных о добыче нет фракций для вашей стороны.",
	["The loot data lists no factions of the other side."] = "В данных о добыче нет фракций другой стороны.",
	["The loot data lists no rewards for this faction."] = "Данные о добыче не содержат наград этой фракции.",
	["The loot data lists no vendors, quest rewards or drops for this event."] = "Данные о добыче не содержат торговцев, наград за задания или добычи для этого события.",
	["The Loot Guide opens out of combat."] = "Loot Guide открывается вне боя.",
	["The Loot Guide stays off while %s is loaded."] = "Loot Guide остается выключенным, пока загружен %s.",
	["The lowest quality a find needs to be written on the Journey. Changing it on a preset turns it into Custom."] = "Минимальное качество находки, чтобы она была записана на «Пути». Изменение в предустановке превращает ее в «Свою».",
	["The mouse wheel turns the pages too."] = "Колесико мыши тоже листает страницы.",
	["The next open step of each attunement and key."] = "Следующий открытый шаг каждого допуска и ключа.",
	["The next step's quest giver on the map and toasts as you go."] = "Тот, кто дает задание следующего шага, на карте и уведомления по пути.",
	["The Night ledger Book in smaller text, short chapters and a slim tracker. Row size stays the Loot Guide's own setting."] = "Книга «Ночной реестр» мельче, короткие главы и узкий трекер. Размер строк остается собственной настройкой Loot Guide.",
	["The numbers come from many short fights with random rolls. The ± range shows how sure they are (95 %)."] = "Числа получены из множества коротких боев со случайными бросками. Диапазон ± показывает их надежность (95 %).",
	["The oldest %d are kept as counts on their levels."] = { one = "Самый старый (%d) хранится как число на своем уровне.", few = "Самые старые %d хранятся как числа на своих уровнях.", many = "Самые старые %d хранятся как числа на своих уровнях.", other = "Самые старые %d хранятся как числа на своих уровнях." },
	["The oldest goes when a new one would pass this. The newest copy from before an EldoUI update has a slot of its own and is always kept."] = "Самый старый удаляется, когда новый превысил бы этот предел. Самая свежая копия перед обновлением EldoUI занимает отдельное место и хранится всегда.",
	["The order your spec values stats in. Drag to change it."] = "Порядок, в котором ваша специализация ценит характеристики. Перетащите, чтобы изменить.",
	["The page the window shows when you open it outside a dungeon. The gear holds a switch for each page and the Catalog's settings."] = "Страница, которую окно показывает при открытии вне подземелья. В шестеренке — переключатель для каждой страницы и настройки Каталога.",
	["the page you left, even inside a dungeon"] = "страница, с которой вы ушли, даже в подземелье",
	["The pages of My Adventure on the Journal window's own dark panel, or on parchment with dark ink. The Book and the character card keep their own Book look."] = "Страницы «Моих приключений» на собственной темной панели окна «Журнал» или на пергаменте с темными чернилами. Книга и карточка персонажа сохраняют собственный вид Книги.",
	["The people you grouped with last first."] = "Сначала люди, с которыми вы были в группе последними.",
	["The people you met and grouped with."] = "Люди, которых вы встретили и с которыми были в группе.",
	["The people you spent the most time with first."] = "Сначала люди, с которыми вы провели больше всего времени.",
	["The people you traveled with: time together and how it was spent, dungeons and quests together, and your notes on them."] = "Люди, с которыми вы путешествовали: время вместе и как оно прошло, общие подземелья и задания и ваши заметки о них.",
	["The places you came to last first."] = "Сначала места, куда вы приходили последними.",
	["The places you spent the most time in first."] = "Сначала места, где вы провели больше всего времени.",
	["The planner is already empty."] = "Планировщик уже пуст.",
	["The planner is empty."] = "Планировщик очищен.",
	["The PvP planner works out weeks from this. Leave 0 to use what you earned in recent weeks."] = "PvP-планировщик рассчитывает по этому значению недели. Оставьте 0, чтобы использовать заработанное за последние недели.",
	["The quest chains come from EldoUI_LootData, which loads a few seconds after login."] = "Цепочки заданий берутся из EldoUI_LootData, который загружается через несколько секунд после входа.",
	["The quest giver is %s."] = "Тот, кто дает задание, находится %s.",
	["The quest giver's exclamation mark right of the bar, like the game's quest icon."] = "Восклицательный знак выдающего задание справа от полосы, как игровой значок задания.",
	["The quest givers are %s."] = "Те, кто дают задание, находятся %s.",
	["The quest tracker leaves room at its bottom for the journal tracker. With Questie, the journal tracker sits right under Questie's list."] = "Трекер заданий оставляет внизу место для трекера журнала. С Questie трекер журнала располагается прямо под списком Questie.",
	["The quests for this instance with your status: open, done or locked."] = "Задания этого подземелья с вашим статусом: открыто, выполнено или закрыто.",
	["The quests you archived, with Restore."] = "Задания в архиве, с кнопкой «Восстановить».",
	["The reminder stays and shows each time, instead of once."] = "Напоминание остается и показывается каждый раз, а не один.",
	["The reputation the item needs, red while you are below it."] = "Репутация, нужная для предмета; красная, пока вы ниже.",
	["The road is waiting. Every zone you visit gets a card."] = "Дорога ждет. Каждая зона, где вы побываете, получит карточку.",
	["The role they had when they sent it."] = "Роль, которая у них была при отправке.",
	["The same fights (same dice) for every set, so the differences are steadier than the totals."] = "Одни и те же бои (одни и те же броски) для каждого комплекта, поэтому разница надежнее итогов.",
	["The Seal of Ascension opens the doors of Upper Blackrock Spire for your whole group."] = "Печать Вознесения открывает двери верхней части пика Черной горы для всей вашей группы.",
	["The search index is built out of combat. Try again in a moment."] = "Поисковый индекс строится вне боя. Попробуйте через мгновение.",
	["The search looks through the %s table."] = "Поиск идет по таблице «%s».",
	["The section My Adventure opens on: Today, a page you pick (Next trips, Journey, Book, Story so far, Keepsakes, Places, Quests, Fellowship, Goals or Notes), or the last one you had open."] = "Раздел, с которого открываются «Мои приключения»: «Сегодня», выбранная страница («Следующие поездки», «Путь», «Книга», «История на сегодня», «Памятное», «Места», «Задания», «Содружество», «Цели» или «Заметки») или последний открытый.",
	["The section you came back from. Alt+Right does the same."] = "Раздел, из которого вы вернулись. Alt+Вправо делает то же.",
	["The section you had open before. Alt+Left or Backspace does the same."] = "Раздел, открытый до этого. Alt+Влево или Backspace делает то же.",
	["The set an item is part of (owned of total) and what a token buys."] = "Комплект, в который входит предмет (есть из общего числа), и что дает жетон.",
	["The set bonuses show once the game has the pieces' details (hover a piece once)."] = "Бонусы комплекта появятся, когда у игры будут сведения о вещах (наведите курсор на вещь один раз).",
	["The set is shared with the Best in Slot page. This can't be undone."] = "Набор общий со страницей «Лучшее в слот (BiS)». Это нельзя отменить.",
	["The Shadowforge Key opens the gates deeper in Blackrock Depths."] = "Ключ Тенегорна открывает ворота в глубину Глубин Черной горы.",
	["The Shapers Terrace"] = "The Shapers Terrace",
	["The simulation is done."] = "Симуляция завершена.",
	["The simulator could not start."] = "Не удалось запустить симулятор.",
	["The simulator folder EldoUI_LootSim is not installed. It comes with EldoUI: put it next to the EldoUI folder in Interface\\AddOns."] = "Папка симулятора EldoUI_LootSim не установлена. Она входит в EldoUI: положите ее рядом с папкой EldoUI в Interface\\AddOns.",
	["The simulator found no damage spells it can use yet."] = "Симулятор пока не нашел заклинаний урона, которые может использовать.",
	["The simulator has no model for your class."] = "У симулятора нет модели для вашего класса.",
	["The simulator has no numbers for this item yet."] = "У симулятора пока нет цифр для этого предмета.",
	["The simulator has no stats for these items, so sets with them are not simulated: "] = "У симулятора нет характеристик этих предметов, поэтому комплекты с ними не симулируются: ",
	["The simulator runs out of combat. Try again when the fight is over."] = "Симулятор работает вне боя. Попробуйте снова после боя.",
	["The Skeleton Key opens the gates of Scholomance."] = "Скелетный ключ открывает ворота Некроситета.",
	["The sound that plays with a wishlist alert."] = "Звук, который играет с оповещением списка желаний.",
	["The step is %s."] = "Шаг находится %s.",
	["The step is ready to hand in."] = "Шаг готов к сдаче.",
	["the story of this quest"] = "история этого задания",
	["The suggestions again."] = "Снова предложения.",
	["The tab lists attunements, keys and dungeon quests once the quest data is loaded."] = "Вкладка покажет допуски, ключи и задания подземелий, когда загрузятся данные о заданиях.",
	["The tavern song: warm and vivid, never false."] = "Трактирная песня: тепло и ярко, но никогда не ложно.",
	["The tour runs out of combat."] = "Обзор проходит вне боя.",
	["The view the Overview button opens first."] = "Вид, который кнопка «Обзор» открывает первым.",
	["The Warlord's Command chain through Blackrock Spire ends with the Drakefire Amulet you need for Onyxia's Lair."] = "Цепочка «Приказ полководца» через пик Черной горы заканчивается Амулетом Драконьего Огня, нужным для Логова Ониксии.",
	["The whole Book in this tone as plain text, in a copy box."] = "Вся Книга в этом тоне простым текстом, в поле для копирования.",
	["The whole journal as one code, to keep or to paste in on another PC. Nothing is sent anywhere."] = "Весь журнал одним кодом, чтобы сохранить или вставить на другом ПК. Ничего никуда не отправляется.",
	["The whole story in this tone as plain text, in a copy box."] = "Вся история в этом тоне простым текстом, в поле для копирования.",
	["The whole story with headings, for a website, a forum, or Discord."] = "Вся история с заголовками, для сайта, форума или Discord.",
	["The window lets the game show through a little. How much: General > Panel opacity. Drag the window's corner grip to change its size."] = "Сквозь окно немного видно игру. Насколько: General > Panel opacity. Потяните за уголок окна, чтобы изменить его размер.",
	["The zone is %d-%d; you are level %d."] = "Зона %d-%d; ваш уровень %d.",
	["The zone list is built out of combat. It shows once the fight is over."] = "Список зон строится вне боя. Он появится, когда бой закончится.",
	["The Zones section lives in the Loot Guide. Turn the Loot Guide on to use it."] = "Раздел «Зоны» находится в Loot Guide. Включите Loot Guide, чтобы им пользоваться.",
	["There is no import to undo."] = "Нет импорта для отмены.",
	["There is no journal to back up yet."] = "Пока нет журнала для резервной копии.",
	["There is no journal to export yet."] = "Пока нет журнала для экспорта.",
	["There is no live position inside dungeons."] = "Внутри подземелий нет текущего положения.",
	["They come back at your next level or after 24 hours."] = "Они вернутся на следующем уровне или через 24 часа.",
	["They may be in another character's fellowship."] = "Возможно, они в содружестве другого персонажа.",
	["They were level %s."] = "Их уровень был %s.",
	["Things you want to work towards. Their progress moves by itself as the game reports it."] = "То, к чему вы хотите стремиться. Прогресс движется сам, по мере того как игра о нем сообщает.",
	["This backup is still being written. Try again in a moment."] = "Эта резервная копия ещё записывается. Попробуйте снова через мгновение.",
	["This can't be undone."] = "Это нельзя отменить.",
	["This client"] = "Этот клиент",
	["This client cannot set a map pin."] = "Этот клиент не может ставить метки на карту.",
	["This client has no group finder window."] = "В этом клиенте нет окна поиска группы.",
	["This game client cannot answer quest questions."] = "Этот клиент игры не может отвечать на вопросы о заданиях.",
	["This game client does not tell add-ons about poisons, oils and other temporary weapon enchants, so they are not counted."] = "Этот клиент игры не сообщает модификациям о ядах, маслах и других временных чарах на оружие, поэтому они не учитываются.",
	["This is how wishlist alerts look."] = "Так выглядят оповещения списка желаний.",
	["this is not a Best in Slot string"] = "это не строка Best in Slot",
	["this is not a wishlist string"] = "это не строка списка желаний",
	["This list is already empty."] = "Этот список уже пуст.",
	["This list shows the factions you have met. Show all factions to see every faction's rewards."] = "В этом списке фракции, с которыми вы встречались. «Показать все фракции» покажет награды каждой фракции.",
	["This page shows where to go next and what is waiting for you."] = "Эта страница показывает, куда идти дальше и что вас ждет.",
	["This place cannot be shown on your map."] = "Это место нельзя показать на вашей карте.",
	["This place has no dungeon map."] = "У этого места нет карты подземелья.",
	["This place has no point on your map yet."] = "У этого места пока нет точки на вашей карте.",
	["This session"] = "Этот сеанс",
	["Thorium Brotherhood"] = "Братство тория",
	["Thunder Bluff"] = "Громовой Утес",
	["check it off"] = "отметить",
	["check it off yourself"] = "отметьте сами",
	["Checked sets run in the next Sets run, all in the same fights."] = "Отмеченные комплекты идут в следующий прогон комплектов, все в одних и тех же боях.",
	["Tier sets"] = "Комплекты тиров",
	["Timbermaw Hold"] = "Древобрюхи",
	["Time"] = "Время",
	["time here"] = "время здесь",
	["Time here"] = "Время здесь",
	["Time in the same group, away from keyboard not counted."] = "Время в одной группе, без учета отсутствия.",
	["Time played at each level, from the level log."] = "Время игры на каждом уровне, по журналу уровней.",
	["Time together"] = "Время вместе",
	["Time you spent here, away from keyboard not counted."] = "Время, проведенное здесь, без учета отсутствия.",
	["to %s"] = "кому: %s",
	["to %s, %s"] = "кому: %s, %s",
	["To level"] = "До уровня",
	["to pick up"] = "можно взять",
	["toast"] = "всплывающее уведомление",
	["Toast (Alerts and Banners)"] = "Всплывающее уведомление (Alerts and Banners)",
	["Toast, else loot toast, else chat"] = "Уведомление, иначе уведомление о добыче, иначе чат",
	["Today"] = "Сегодня",
	["Together"] = "Вместе",
	["Tokens"] = "Жетоны",
	["Tokens come from EldoUI_LootData. Install it next to EldoUI to list them."] = "Жетоны берутся из EldoUI_LootData. Установите его рядом с EldoUI, чтобы увидеть их список.",
	["Tokens shows what each raid token buys for a class."] = "Жетоны показывают, что покупает каждый рейдовый жетон для класса.",
	["Tone"] = "Тон",
	["too costly for its gain"] = "слишком дорого для своей пользы",
	["too low for it"] = "слишком низкий уровень",
	["Too low level"] = "Слишком низкий уровень",
	["too slow to cast on a dummy"] = "слишком медленно для применения на манекене",
	["Tooltip line settings"] = "Настройки строк подсказки",
	["Tooltip: %s"] = "Подсказка: %s",
	["Tooltips"] = "Подсказки",
	["Tooltips and map"] = "Подсказки и карта",
	["total %s"] = "всего %s",
	["Total: %s %s"] = "Всего: %s %s",
	["totems are not modeled"] = "тотемы не моделируются",
	["Track"] = "Отслеживать",
	["Tracker and buttons"] = "Трекер и кнопки",
	["Tracker height"] = "Высота трекера",
	["Trainer"] = "Учитель",
	["trainer"] = "учитель",
	["Trainer: %s %d"] = "Учитель: %s %d",
	["Trash and zone drops"] = "Добыча с мелочи и зоны",
	["Traveling"] = "В пути",
	["Trinket"] = "Аксессуар",
	["try on"] = "примерить",
	["Try on"] = "Примерить",
	["Try on set"] = "Примерить комплект",
	["Turbo (16 ms a frame)"] = "Турбо (16 мс на кадр)",
	["Turn Forever Journal off in the AddOns list and reload, so the two journals do not both write."] = "Отключите Forever Journal в списке модификаций и перезагрузите интерфейс, чтобы оба журнала не писали одновременно.",
	["Turn in: %s"] = "Сдать: %s",
	["Turn it on"] = "Включить",
	["Turn on Alts"] = "Включить Персонажей",
	["Turn on Attunements to set this goal."] = "Включите Допуски, чтобы поставить эту цель.",
	["Turn on Blizzard UI > Objective / quest tracker > Move and scale to keep the quest list clear of the journal tracker."] = "Включите Blizzard UI > Objective / quest tracker > Move and scale, чтобы список заданий не налезал на трекер журнала.",
	["Turn on sharing"] = "Включить обмен",
	["Turn on sharing to ask guild and group members who use EldoUI for their attunements and to send yours. Nothing is sent until you click Ask or Send mine."] = "Включите обмен, чтобы спрашивать допуски у членов гильдии и группы, использующих EldoUI, и отправлять свои. Ничего не отправляется, пока вы не нажмете «Спросить» или «Отправить мои».",
	["Turn on the Alts module to see the attunements of your other characters here."] = "Включите модуль Персонажи, чтобы видеть здесь допуски других ваших персонажей.",
	["Turn on the Loot Guide"] = "Включить Loot Guide",
	["Turn on the Nameplates module first."] = "Сначала включите модуль Nameplates.",
	["Turn-in"] = "Сдача",
	["Turns Hide finished off."] = "Выключает «Скрыть выполненные».",
	["Turns off My level only."] = "Выключает «Только мой уровень».",
	["Turns on Share with guild and group (Attunements settings)."] = "Включает «Делиться с гильдией и группой» (настройки допусков).",
	["Turns the filters off."] = "Выключает фильтры.",
	["Two quick choices for this character. Both can be changed later."] = "Два быстрых выбора для этого персонажа. Оба можно изменить позже.",
	["two weapons"] = "два оружия",
	["Two-hand"] = "Двуручное",
	["Two-hander in the main hand"] = "Двуручное в правой руке",
	["Type"] = "Тип",
	["Type %s in chat for the My Adventure settings."] = "Введите %s в чате, чтобы открыть настройки «Моих приключений».",
	["Type a little more"] = "Введите чуть больше",
	["Type the creature's name, or use your target."] = "Введите имя существа или используйте свою цель.",
	["Type the dungeon's name, for example The Deadmines."] = "Введите название подземелья, например Мертвые копи.",
	["Type the faction's name, for example Stormwind."] = "Введите название фракции, например Штормград.",
	["Type the place's name, for example Stranglethorn Vale or Frostmane Hold."] = "Введите название места, например Тернистая долина.",
	["Type the profession's name, for example First Aid."] = "Введите название профессии, например Первая помощь.",
	["Type three letters in the box at the top (or an alias such as dm or zf) and press Enter."] = "Введите три буквы в поле сверху (или сокращение вроде dm или zf) и нажмите Enter.",
	["Uncommon"] = "Необычное",
