	["Welcome card put away."] = "Приветственная карточка убрана.",
	["Welcome to the Loot Guide"] = "Добро пожаловать в Loot Guide",
	["Well rested"] = "Хорошо отдохнувший",
	["Well rested (%d%% of a level): a good time for a dungeon."] = "Хорошо отдохнувший (%d%% уровня): хорошее время для подземелья.",
	["What do you want to do?"] = "Что вы хотите сделать?",
	["What each faction sells or gives at every standing, how far you are from it and which rewards are upgrades for you."] = "Что каждая фракция продает или дает на каждом уровне отношения, сколько вам до него и какие награды для вас улучшения.",
	["What each raid token or turn-in item buys for a class."] = "Что каждый рейдовый жетон или предмет для сдачи покупает для класса.",
	["What happened here"] = "Что здесь случилось",
	["What I wear"] = "Что на мне",
	["What is ahead"] = "Что впереди",
	["What is left are raids, attunements, and reputation. Next trips shows them once you turn on raids, and the Attunements page has every key."] = "Остались рейды, допуски и репутация. «Следующие поездки» покажут их, когда вы включите рейды, а на странице «Допуски» есть каждый ключ.",
	["What is left are raids, attunements, and reputation. Nothing else fits right now; put-away cards come back after 24 hours."] = "Остались рейды, допуски и репутация. Больше ничего сейчас не подходит; убранные карточки вернутся через 24 часа.",
	["What opens at level %d"] = "Что открывается на уровне %d",
	["What opens at the next level"] = "Что открывается на следующем уровне",
	["What shows"] = "Что показывать",
	["What the game's quest lines report on this map. Copy it (Ctrl+C) and send it to EldoUI's authors."] = "Что сообщают цепочки заданий игры на этой карте. Скопируйте (Ctrl+C) и отправьте авторам EldoUI.",
	["What the item adds over what you wear, with your stat priority."] = "Что предмет добавляет к надетому, с вашим приоритетом характеристик.",
	["What the journal writes down, the look of its pages, and how the ideas are ranked. /eui tour journal shows this tour again."] = "Что журнал записывает, как выглядят его страницы и как ранжируются идеи. /eui tour journal снова покажет этот обзор.",
	["What the journal wrote down since you last logged out."] = "Что журнал записал с вашего последнего выхода из игры.",
	["What the pages show"] = "Что показывают страницы",
	["What the tab has loaded. Chains come from EldoUI_LootData (Classic values; WoW: Forever may differ)."] = "Что загрузила вкладка. Цепочки берутся из EldoUI_LootData (значения Classic; в WoW: Forever может отличаться).",
	["What was read"] = "Что было прочитано",
	["What would you like to work towards?"] = "К чему вы хотите стремиться?",
	["What you wear, Best in Slot and your plan sets compared as DPS from the same fights."] = "Надетое, Best in Slot и ваши планы комплектов, сравненные по DPS в одних и тех же боях.",
	["When a backup is taken by itself, 8 seconds after you log in and out of combat."] = "Когда резервная копия делается сама, через 8 секунд после входа в игру и вне боя.",
	["When someone asks"] = "Когда кто-то спрашивает",
	["When this note should show again as a reminder. It picks one from what you write until you choose yourself."] = "Когда эта заметка должна снова появиться как напоминание. Она выбирает вариант по тому, что вы пишете, пока вы не выберете сами.",
	["When you apply a layout preset, the Book takes the look of the style that fits it: EldoUI, Storybook or Compact. What the journal shows is kept."] = "Когда вы применяете шаблон раскладки, Книга берет вид подходящего стиля: EldoUI, Книга историй или Компактно. То, что показывает журнал, сохраняется.",
	["When you enter %s"] = "Когда вы входите в %s",
	["When you open a profession"] = "Когда вы открываете профессию",
	["When you reach level %d"] = "Когда вы достигаете уровня %d",
