	["Where the alert shows. Every alert also writes one chat line so you can read it later."] = "Где появляется оповещение. Каждое оповещение также пишет строку в чат, чтобы вы могли прочесть ее позже.",
	["Where the icon sits on the plate. Right of the bar comes after the elite and quest icons."] = "Где значок стоит на индикаторе. «Справа от полосы» идет после значков элиты и заданий.",
	["Where the item drops and how often, and the vendors that sell it with the cost. Hold Shift for more sources and the drops you saw yourself."] = "Где предмет выпадает и как часто, и торговцы, которые его продают, с ценой. Удерживайте Shift, чтобы увидеть больше источников и добычу, которую вы видели сами.",
	["where the loot data comes from"] = "откуда берутся данные о добыче",
	["Where this comes from"] = "Откуда это",
