	["You have already finished that quest chain."] = "Вы уже прошли эту цепочку заданий.",
	["You have been here %d times."] = { one = "Вы были здесь %d раз.", few = "Вы были здесь %d раза.", many = "Вы были здесь %d раз.", other = "Вы были здесь %d раза." },
	["You have been here."] = "Вы уже бывали здесь.",
	["You have done this quest."] = "Вы выполнили это задание.",
	["You have it"] = "Есть у вас",
	["You have not been inside yet."] = "Вы еще не были внутри.",
	["You have not grouped on this character yet; your player notes know them."] = "Этим персонажем вы еще не были в группе; ваши заметки об игроках их знают.",
	["You have not met this faction yet."] = "Вы еще не встречали эту фракцию.",
	["You have run dungeons with %s adventurers."] = { one = "Вы проходили подземелья с %s искателем приключений.", few = "Вы проходили подземелья с %s искателями приключений.", many = "Вы проходили подземелья с %s искателями приключений.", other = "Вы проходили подземелья с %s искателями приключений." },
	["You have shared the road with %s adventurers, %s in all."] = { one = "Вы делили дорогу с %s искателем приключений, всего %s.", few = "Вы делили дорогу с %s искателями приключений, всего %s.", many = "Вы делили дорогу с %s искателями приключений, всего %s.", other = "Вы делили дорогу с %s искателями приключений, всего %s." },
	["You have them all."] = "У вас есть все.",
	["You imported before: only what is new since then comes in."] = "Вы уже импортировали раньше: войдет только новое с тех пор.",
	["You know this recipe."] = "Вы знаете этот рецепт.",
	["You left %s with a quest unfinished."] = "Вы покинули %s с невыполненным заданием.",
	["You missed one"] = "Вы пропустили одно",
	["You need %d skill to learn it."] = "Чтобы изучить, нужен навык %d.",
	["You own something better"] = "У вас есть кое-что получше",
	["You ran dungeons together before the journal kept company."] = "Вы проходили подземелья вместе до того, как журнал начал записывать спутников.",
	["You ran it %d times at this level."] = { one = "Вы проходили его %d раз на этом уровне.", few = "Вы проходили его %d раза на этом уровне.", many = "Вы проходили его %d раз на этом уровне.", other = "Вы проходили его %d раза на этом уровне." },
	["You rate items with the simulator: this runs your Best in Slot set now (out of combat, in small steps)."] = "Вы оцениваете предметы симулятором: сейчас запускается ваш комплект Best in Slot (вне боя, небольшими шагами).",
	["you wear it"] = "надето на вас",
	["You wear this item"] = "Этот предмет надет на вас",
	["You were away %s."] = "Вас не было %s.",
	["You were away %s. You left off in %s at level %d."] = "Вас не было %s. Вы остановились: %s, уровень %d.",
	["You were away %s. You left off in %s."] = "Вас не было %s. Вы остановились: %s.",
	["Your /played time, from the game."] = "Ваше время /played, по данным игры.",
	["Your active goals under the quest tracker. Click a to-do to check it."] = "Ваши активные цели под списком заданий. Щелкните по пункту, чтобы отметить его.",
	["Your active wishlist by slot. Click a slot to choose its main pick; the model wears the picks."] = "Ваш активный список желаний по ячейкам. Щелкните по ячейке, чтобы выбрать главный вариант; модель носит выбранное.",
	["Your active wishlist has no gear. Star items in the Journal or Search; they show here by slot."] = "В вашем активном списке желаний нет снаряжения. Отмечайте предметы звездочкой в Журнале или Поиске; они появятся здесь по ячейкам.",
	["Your Best in Slot run is outdated."] = "Ваш прогон Best in Slot устарел.",
	["Your big moments as cards: first kills, epic finds, standings, mounts, and the moments you kept, with your firsts."] = "Ваши большие моменты в виде карточек: первые победы, эпические находки, отношения, транспорт и сохраненные моменты, с вашими «первыми разами».",
	["Your big moments at these levels."] = "Ваши большие моменты на этих уровнях.",
	["Your character card"] = "Ваша карточка персонажа",
	["Your character card as a few lines of text. Companion names are left out."] = "Ваша карточка персонажа в несколько строк текста. Имена спутников опущены.",
	["Your character card as Markdown"] = "Ваша карточка персонажа в Markdown",
	["Your character card on a dimmed screen, ready for your own screenshot key."] = "Ваша карточка персонажа на затемненном экране, готовая для вашей клавиши снимка экрана.",
	["Your character's journal, the first tab of this window: where to go next, what is waiting for you, and everything you have done."] = "Журнал вашего персонажа, первая вкладка этого окна: куда идти дальше, что вас ждет и все, что вы сделали.",
	["Your character's journal: what you did and where, keepsakes, goals, notes, attunements, and where to go next."] = "Журнал вашего персонажа: что вы сделали и где, памятное, цели, заметки, допуски и куда идти дальше.",
	["Your character's journal: where to go next, what is waiting for you, your goals and notes, and the story so far. /eui tour journal shows it part by part."] = "Журнал вашего персонажа: куда идти дальше, что вас ждет, ваши цели и заметки и история на сегодня. /eui tour journal покажет его по частям.",
	["Your character's story in a few lines, with the level river, your numbers, the eras, and ways to share it."] = "История вашего персонажа в нескольких строках, с рекой уровней, вашими цифрами, эпохами и способами поделиться ею.",
	["Your character's story in a few pages."] = "История вашего персонажа на нескольких страницах.",
	["Your characters"] = "Ваши персонажи",
	["Your characters and how far each one is (Alts module)."] = "Ваши персонажи и прогресс каждого (модуль Персонажи).",
	["your class"] = "ваш класс",
	["Your class (Sets for my class only), all classes or one other class."] = "Ваш класс («Комплекты только моего класса»), все классы или один другой класс.",
	["Your class can't use it"] = "Ваш класс не может это использовать",
	["Your class can't use this"] = "Ваш класс не может использовать это",
	["Your DPS with what you wear, the damage of each ability, what one more point of each stat is worth, and what the simulator read."] = "Ваш DPS в надетом, урон каждой способности, сколько стоит одно очко каждой характеристики и что прочитал симулятор.",
	["Your DPS: %.1f ± %.1f (estimate)"] = "Ваш DPS: %.1f ± %.1f (оценка)",
	["Your factions with your standing. Pick one to see what it sells and gives at each standing."] = "Ваши фракции с вашим отношением. Выберите одну, чтобы увидеть, что она продает и дает на каждом уровне.",
	["Your filters hide all %d drops."] = { one = "Ваши фильтры скрывают %d предмет добычи.", few = "Ваши фильтры скрывают все %d предмета добычи.", many = "Ваши фильтры скрывают все %d предметов добычи.", other = "Ваши фильтры скрывают все %d предмета добычи." },
	["Your filters hide every attunement. Show finished attunements?"] = "Ваши фильтры скрывают все допуски. Показать выполненные?",
	["Your first attunement step is open:"] = "Ваш первый шаг допуска открыт:",
	["Your first attunement step."] = "Ваш первый шаг допуска.",
	["Your first boss kill."] = "Ваша первая победа над боссом.",
	["Your first dungeon is waiting. These fit your level:"] = "Ваше первое подземелье ждет. Эти подходят вашему уровню:",
	["Your first epic find."] = "Ваша первая эпическая находка.",
	["Your first mount comes from your race's mount vendor once you have the level and the gold it asks for."] = "Первый транспорт продает торговец верховыми животными вашей расы, когда у вас будут нужный уровень и золото.",
	["Your first mount comes from your race's mount vendor once you have the level and the gold it asks for. Meanwhile:"] = "Первый транспорт продает торговец верховыми животными вашей расы, когда у вас будут нужный уровень и золото. А пока:",
	["Your first mount."] = "Ваш первый транспорт.",
	["Your Forever Journal history for this character is now in My Adventure (%s)."] = "История Forever Journal этого персонажа теперь в «Моих приключениях» (%s).",
	["Your gear is better for %s"] = "Ваше снаряжение лучше для %s",
	["Your group"] = "Ваша группа",
	["Your group is small for a %d-player dungeon."] = "Ваша группа мала для подземелья на %d игроков.",
	["Your hearthstone is set to %s."] = "Ваш камень возвращения привязан к месту: %s.",
	["Your honor, marks and rank. Costs show once you have visited the vendor."] = "Ваши честь, знаки и звание. Цены появятся, когда вы посетите торговца.",
	["Your journal"] = "Ваш журнал",
	["Your journal as it is now is backed up first either way."] = "Ваш журнал в нынешнем виде в любом случае сначала сохраняется.",
	["Your journal is back as it was then."] = "Ваш журнал вернулся к тому состоянию.",
	["Your journal starts today"] = "Ваш журнал начинается сегодня",
	["Your last run took %s."] = "Ваш последний поход занял %s.",
	["Your level"] = "Ваш уровень",
	["Your levels while you were grouped with them."] = "Ваши уровни, пока вы были с ними в группе.",
	["Your loot journal, Best in Slot planner and wishlist in one window. This short tour shows each part; Skip ends it, and Start tour on the settings page brings it back."] = "Ваш журнал добычи, планировщик Best in Slot и список желаний в одном окне. Этот короткий обзор показывает каждую часть; «Пропустить» завершает его, а «Начать обзор» на странице настроек возвращает.",
	["Your loot list"] = "Ваш список добычи",
	["Your name, or the pronoun you pick. Exports always use your name."] = "Ваше имя или выбранное вами местоимение. В экспорте всегда используется ваше имя.",
	["Your note"] = "Ваша заметка",
	["Your note on \"%s\" (up to %d letters; empty removes it):"] = "Ваша заметка о «%s» (до %d букв; пустая удаляет ее):",
	["Your note on them, kept in Player Notes and shown on their tooltip."] = "Ваша заметка о них, хранится в «Заметках об игроках» и показывается в их подсказке.",
	["Your note, from Player Notes"] = "Ваша заметка из «Заметок об игроках»",
	["Your note: %s"] = "Ваша заметка: %s",
	["Your notes."] = "Ваши заметки.",
	["Your own level times show here once you have a few levels behind you."] = "Ваше собственное время по уровням появится здесь, когда за плечами будет несколько уровней.",
	["your own list"] = "ваш собственный список",
	["Your own plan. Click a slot to pick items; right-click the chip to rename it."] = "Ваш собственный план. Щелкните по ячейке, чтобы выбрать предметы; щелчок правой кнопкой по ярлыку переименовывает его.",
	["Your own side's factions, or the other side's (to see what they get)."] = "Фракции вашей стороны или другой (чтобы увидеть, что получают они).",
	["Your pet is not out. Call it and press Sim again."] = "Ваш питомец не призван. Призовите его и снова нажмите «Сим».",
	["Your plan sets are empty. Pick items for them on the Best in Slot page or in the Planner tab."] = "Ваши планы комплектов пусты. Выберите для них предметы на странице Best in Slot или во вкладке «Планировщик».",
	["Your plan sets are shared with the Best in Slot page. Rename them there."] = "Ваши планы комплектов общие со страницей Best in Slot. Переименуйте их там.",
	["Your professions come first with your skill. Open your profession window once so known recipes and their colors show."] = "Ваши профессии идут первыми с вашим навыком. Откройте окно профессии один раз, чтобы появились известные рецепты и их цвета.",
	["your quest log"] = "ваш журнал заданий",
	["Your quest log is empty"] = "Ваш журнал заданий пуст",
	["Your quest log is empty."] = "Ваш журнал заданий пуст.",
	["Your quest log now, with where and when you took each quest."] = "Ваш журнал заданий сейчас, с местом и временем, где и когда вы взяли каждое задание.",
	["Your quests here: %s."] = { one = "Ваше задание здесь: %s.", few = "Ваши задания здесь: %s.", many = "Ваши задания здесь: %s.", other = "Ваши задания здесь: %s." },
	["Your race can't use it"] = "Ваша раса не может это использовать",
	["Your runs"] = "Ваши походы",
	["Your runs here: first visit, time inside, bosses beaten, who came along, and what is still to do."] = "Ваши походы сюда: первое посещение, время внутри, побежденные боссы, кто был с вами и что еще осталось.",
	["Your runs there"] = "Ваши походы туда",
	["Your screenshot key: %s."] = "Ваша клавиша снимка экрана: %s.",
	["Your sets are simulated. Open the Sets tab to compare them."] = "Ваши комплекты просимулированы. Откройте вкладку «Комплекты», чтобы сравнить их.",
	["Your side"] = "Ваша сторона",
	["Your skill: %d"] = "Ваш навык: %d",
	["your spec"] = "ваша специализация",
	["Your spec, the armor you wear and where gear may come from. This one list counts everywhere: For You, tooltips and roll advice."] = "Ваша специализация, броня, которую вы носите, и откуда может прийти снаряжение. Этот один список действует везде: «Для вас», подсказки и советы при розыгрыше.",
	["Your story as it happened: chapters by level, day, or zone, with keepsakes, finds, and pinned notes."] = "Ваша история как она была: главы по уровню, дню или зоне, с памятным, находками и закрепленными заметками.",
	["Your story as Markdown"] = "Ваша история в Markdown",
	["Your story as text"] = "Ваша история текстом",
	["Your story chapter by chapter: levels, places, first kills, finds, and the people you met. Keepsakes and the story so far sit beside it."] = "Ваша история глава за главой: уровни, места, первые победы, находки и люди, которых вы встретили. Памятное и история на сегодня — рядом.",
	["Your story from level 1 to 60 as a book in chapters, in the tone you choose, with a cover for every part."] = "Ваша история с 1 по 60 уровень как книга в главах, в выбранном тоне, с обложкой для каждой части.",
	["Your story in chapters, page by page."] = "Ваша история в главах, страница за страницей.",
	["Your story in chapters, written from what the journal recorded."] = "Ваша история в главах, написанная по тому, что записал журнал.",
	["Your story starts with the first thing the journal writes down."] = "Ваша история начинается с первого, что запишет журнал.",
	["your talents"] = "ваши таланты",
	["Your target."] = "Ваша цель.",
	["Your two plan sets (the same as on the Best in Slot page). Click a slot to pick an item or drop one from your bags."] = "Ваши два плана комплектов (те же, что на странице Best in Slot). Щелкните по ячейке, чтобы выбрать предмет, или перетащите его из сумок.",
	["Your whole story, chapter by chapter."] = "Вся ваша история, глава за главой.",
	["Your whole story, place by place."] = "Вся ваша история, место за местом.",
	["Your whole story, with the keepsakes in their place."] = "Вся ваша история, с памятным на своих местах.",
	["Your wishlist alerts you when the item drops."] = "Ваш список желаний оповестит вас, когда предмет выпадет.",
	["Your wishlist is empty"] = "Ваш список желаний пуст",
	["Zandalar Tribe"] = "Племя Зандалар",
	["Zone"] = "Зона",
	["Zone Info"] = "Zone Info",
	["Zone list"] = "Список зон",
	["Zone map"] = "Карта игровой зоны",
	["Zone Quests"] = "Задания зоны",
	["Zone quests come from EldoUI_LootData. Install that folder next to EldoUI to see every zone; until then only the quests the game showed you are listed."] = "Задания зон берутся из EldoUI_LootData. Установите эту папку рядом с EldoUI, чтобы видеть все зоны; до тех пор показываются только задания, которые вам показала игра.",
	["Zone: %s"] = "Зона: %s",
	["Zone: All"] = "Зона: все",
	["Zones"] = "Зоны",
	["Zones and dungeons."] = "Зоны и подземелья.",
	["Zones and mobs"] = "Зоны и противники",
	["Zones for your level"] = "Зоны по вашему уровню",
	["Zones for your level or all zones. The guide follows your zone until you click one."] = "Зоны по вашему уровню или все зоны. Путеводитель следует за вашей зоной, пока вы не щелкнете по одной.",
	["Zones for your level, or every zone the loot data knows creatures for."] = "Зоны по вашему уровню или каждая зона, для которой данные о добыче знают существ.",
	["Zones with quests for your level that you have not done yet."] = "Зоны с заданиями по вашему уровню, которые вы еще не выполнили.",
	["Zoom in"] = "Приблизить",
	["Zoom out"] = "Отдалить",
	["Zooms so the whole chain fits the window."] = "Масштабирует так, чтобы вся цепочка поместилась в окне.",
	["Zul'Gurub sets"] = "Комплекты Зул'Гуруба",
	["~%s to %d"] = "~%s до уровня %d",
	["Drag to make the window bigger or smaller; the content follows. Ctrl+mouse wheel on the title bar zooms."] = "Перетащите, чтобы увеличить или уменьшить окно; содержимое подстроится. Ctrl+колесо мыши на заголовке меняет масштаб.",
	["Window size"] = "Размер окна",
	["Opens at level %d in %s."] = "Доступно с уровня %d: %s.",
	["Opens at level %d with %s in %s."] = "Открывается на уровне %d у %s (%s).",
	["Opens at level %d."] = "Открывается на уровне %d.",
	["It ends with %s."] = "В конце награда: %s.",
	["Tracks whether you have the Dalaran Sewer Key. One key holder can open the gate for the group; you do not need to finish the dungeon quest first."] = "Показывает, есть ли у вас ключ от канализации Даларана. Один владелец ключа может открыть ворота для всей группы; сначала завершать задание в подземелье не требуется.",
	["%d more drops were not kept."] = { one = "Еще %d предмет не сохранен.", few = "Еще %d предмета не сохранено.", many = "Еще %d предметов не сохранено.", other = "Еще %d предмета не сохранено." },
	["%s runs"] = { one = "%s заход", few = "%s захода", many = "%s заходов", other = "%s захода" },
	["%s runs added to your journal."] = { one = "%s заход добавлен в ваш журнал.", few = "%s захода добавлено в ваш журнал.", many = "%s заходов добавлено в ваш журнал.", other = "%s захода добавлено в ваш журнал." },
	["Accept merges them into this character's runs: nothing is lost, and a backup is taken first."] = "Принять — объединить с заходами этого персонажа: ничего не потеряется, а перед этим будет сделана резервная копия.",
	["An item"] = "Предмет",
	["Attunement lines on item and character tooltips have their own switches on the Tooltip page."] = "У строк допусков в подсказках предметов и персонажей есть свои переключатели на странице «Подсказки».",
	["Attunements, keys and dungeon quest chains as a Loot Guide tab. Progress comes from your quest log, bags and reputation."] = "Допуски, ключи и цепочки заданий подземелий на вкладке Loot Guide. Прогресс берется из журнала заданий, сумок и репутации.",
	["Backups are copies of this journal in your saved data. The game writes them to disk when you log out or /reload."] = "Резервные копии — это копии этого журнала в ваших сохраненных данных. Игра записывает их на диск, когда вы выходите из игры или делаете /reload.",
	["Backups of your runs"] = "Резервные копии ваших заходов",
	["Classic: chances from Classic data; Forever may differ. Seen: what you looted yourself, with the number of kills (needs Mob and Loot Info)."] = "Classic: шансы из данных Classic; в Forever могут отличаться. Видено: что вы добыли сами, с числом убийств (нужно «Сведения о существах и добыче»).",
	["Copy a runs code"] = "Скопировать код заходов",
	["Creatures that can drop an item that starts a quest get a tooltip line and a small icon on their nameplate."] = "Существа, с которых может выпасть предмет, начинающий задание, получают строку в подсказке и маленький значок на индикаторе здоровья.",
	["Delete this run?"] = "Удалить этот заход?",
	["Every dungeon and raid run stays in your journal with who was in it. Its own code keeps them safe or moves them to another PC."] = "Каждый заход в подземелье и рейд остается в вашем журнале вместе с теми, кто в нем был. Свой код хранит их в сохранности или переносит на другой ПК.",
	["Every zone's quests in the Loot Guide's Catalog: how many you have done, what is left and who gives them."] = "Задания каждой зоны в каталоге Loot Guide: сколько вы выполнили, что осталось и кто их выдает.",
	["Everyone passed"] = "Все отказались",
	["For this character: your stat weights (fast, the same as the Upgrades arrows), or the simulator (DPS against a target dummy, run when you press Sim)."] = "Для этого персонажа: веса характеристик (быстро, те же, что у стрелок улучшений) или симулятор (DPS по тренировочному манекену, запускается кнопкой «Сим»).",
	["Forget"] = "Забыть",
	["Forget this name?"] = "Забыть это имя?",
	["Green is done, the accent is in your quest log, yellow is available, gray is locked. An unreported step counts once the next is done."] = "Зеленый — выполнено, акцентный цвет — в журнале заданий, желтый — доступно, серый — заблокировано. Шаг без отметки засчитывается, как только выполнен следующий.",
	["Journal run backups of %s"] = "Резервные копии заходов журнала: %s",
	["Journal runs backup"] = "Резервная копия заходов журнала",
	["Journal runs of %s"] = "Заходы журнала: %s",
	["Load the runs of %s (saved %s) into this character?"] = "Загрузить заходы персонажа %s (сохранены %s) в этого персонажа?",
	["Loads a runs code (!EUJR1!). You see what it holds, then Merge or Replace."] = "Загружает код заходов (!EUJR1!). Вы видите его содержимое и затем выбираете «Объединить» или «Заменить».",
	["Loot Guide in EldoUI %s. %s opens the window, %s the simulator, %s lists every command."] = "Loot Guide в EldoUI %s. %s открывает окно, %s — симулятор, %s выводит все команды.",
	["Merge adds the runs your journal is missing and never adds one twice. Replace puts your runs back exactly as they were then."] = "«Объединить» добавляет заходы, которых нет в вашем журнале, и никогда не добавляет один дважды. «Заменить» возвращает ваши заходы в точности к тому состоянию.",
	["Need (off spec)"] = "Мне это нужно (вторая специализация)",
	["No backup of your runs yet."] = "Резервной копии ваших заходов пока нет.",
	["No roll"] = "Без броска",
	["Nothing to read. Paste a runs code first."] = "Нечего читать. Сначала вставьте код заходов.",
	["On a creature that can drop an item that starts a quest: the item, the quest and the drop chance, until you have the item or did the quest."] = "На существе, с которого может выпасть предмет, начинающий задание: предмет, задание и шанс добычи, пока у вас нет предмета или задание не выполнено.",
	["Paste a runs code"] = "Вставить код заходов",
	["Paste a runs code from EldoUI (!EUJR1!). You see what it holds before anything changes."] = "Вставьте код заходов из EldoUI (!EUJR1!). Вы увидите содержимое до того, как что-то изменится.",
	["Pick a backup of your runs, then Merge or Replace. Your runs are backed up first."] = "Выберите резервную копию заходов, затем «Объединить» или «Заменить». Сначала создается резервная копия ваших заходов.",
	["Press Ctrl+C to copy the code. Use \"Paste a runs code\" on this PC or another to restore your runs. Nothing is sent anywhere."] = "Нажмите Ctrl+C, чтобы скопировать код. Используйте «Вставить код заходов» на этом или другом ПК, чтобы восстановить заходы. Ничего никуда не отправляется.",
	["Restore your runs"] = "Восстановить заходы",
	["Restore your runs from %s?"] = "Восстановить заходы от %s?",
	["Runs code"] = "Код заходов",
	["Show %d earlier runs"] = { one = "Показать еще %d заход", few = "Показать еще %d захода", many = "Показать еще %d заходов", other = "Показать еще %d захода" },
	["Someone"] = "Кто-то",
	["That is not a runs code. A runs code starts with !EUJR1!."] = "Это не код заходов. Код заходов начинается с !EUJR1!.",
	["The name leaves every run and your companions; the runs and everyone else stay. Undo brings it back for 7 days."] = "Имя исчезнет из всех заходов и спутников; заходы и все остальные останутся. «Отменить» вернет его в течение 7 дней.",
	["The run leaves your journal; everything else stays. Undo brings it back for 7 days."] = "Заход исчезнет из журнала; все остальное останется. «Отменить» вернет его в течение 7 дней.",
	["The runs of %s, saved %s."] = "Заходы персонажа %s, сохранены %s.",
	["The tooltip line has its own switch on the Tooltip page. The chance follows the Loot Guide's Drop chances setting."] = "У строки подсказки есть свой переключатель на странице «Подсказки». Шанс следует настройке «Шансы добычи» в Loot Guide.",
	["There are no runs to back up yet."] = "Пока нет заходов для резервной копии.",
	["This can be done out of combat only."] = "Вы не можете этого делать, пока участвуете в бою",
	["Transmog"] = "Трансмогрификация",
	["Updating the list of runs. It fills in by itself in a moment."] = "Обновление списка заходов. Он заполнится сам через мгновение.",
	["What the pages show; everything is always written down. Essentials: levels, deaths, notes, goals. Storyteller: adds spells, professions and places. Chronicler: everything."] = "Что показывают страницы; записывается всегда все. Главное: уровни, смерти, заметки, цели. Рассказчик: добавляет заклинания, профессии и места. Летописец: все.",
	["with %s others"] = { one = "с %s другим", few = "с %s другими", many = "с %s другими", other = "с %s другими" },
	["Won with you"] = "Выиграно с вами",
	["Your character's journal in the Journal window: a diary that writes itself, keepsakes, places, quests, goals and notes, your story from 1 to 60 and where to go next."] = "Журнал вашего персонажа в окне журнала: дневник, который пишется сам, памятное, места, задания, цели и заметки, ваша история с 1 по 60 уровень и куда идти дальше.",
	["Your runs are back as they were then."] = "Ваши заходы вернулись к тому состоянию.",
	["Your runs as one code, to keep or to paste in on another PC. Nothing is sent anywhere."] = "Ваши заходы одним кодом, чтобы сохранить или вставить на другом ПК. Ничего никуда не отправляется.",
	["Your runs as they are now are backed up first either way."] = "Ваши заходы в нынешнем виде в любом случае сначала сохраняются.",
} end)
